insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tartiflette', 'Tartiflette', array['tartiflette savoyarde']::text[], 'dish', $r$[{"title":"Tartiflette au reblochon","intro":"Le grand classique savoyard : des pommes de terre fondantes, des lardons et un reblochon qui gratine.","minutes":60,"calories":750,"difficulty":"Facile","imageSearch":"tartiflette potato gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre entières 20 min dans l'eau bouillante salée.","timer":{"label":"Cuisson","min":20}},{"text":"Préchauffe le four à 200 °C. Coupe les pommes de terre en rondelles.","timer":null},{"text":"Fais revenir les oignons émincés et les lardons 8 min à la poêle, puis verse le vin blanc.","timer":{"label":"Poêle","min":8}},{"text":"Dans un plat, alterne pommes de terre, lardons et crème. Pose le reblochon coupé en deux, croûte vers le haut.","timer":null},{"text":"Enfourne 25 min, jusqu'à ce que ce soit bien doré.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"La classique","change":""},{"title":"Tartiflette légère","intro":"Toute la gourmandise de la tartiflette, en plus léger pour la semaine.","minutes":55,"calories":520,"difficulty":"Facile","imageSearch":"light tartiflette potato","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromages blanc","qty":200,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min dans l'eau bouillante salée.","timer":{"label":"Cuisson","min":20}},{"text":"Préchauffe le four à 200 °C. Coupe les pommes de terre en rondelles.","timer":null},{"text":"Fais revenir les oignons émincés 5 min à la poêle avec le jambon.","timer":{"label":"Poêle","min":5}},{"text":"Mélange le fromage blanc avec du sel et du poivre, puis avec les pommes de terre, l'oignon et le jambon.","timer":null},{"text":"Verse dans un plat, ajoute un demi-reblochon en tranches et enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Plus légère","change":"La crème est remplacée par du fromage blanc et le reblochon est réduit de moitié."},{"title":"Tartiflette végétarienne aux champignons","intro":"Des champignons dorés à la place des lardons : le reblochon fait le reste.","minutes":60,"calories":680,"difficulty":"Facile","imageSearch":"mushroom tartiflette gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min dans l'eau bouillante salée.","timer":{"label":"Cuisson","min":20}},{"text":"Préchauffe le four à 200 °C. Coupe les pommes de terre en rondelles.","timer":null},{"text":"Fais dorer les champignons émincés et les oignons 10 min à la poêle.","timer":{"label":"Poêle","min":10}},{"text":"Alterne pommes de terre, champignons et crème dans un plat, puis pose le reblochon coupé en deux.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Végétarienne","change":"Les lardons sont remplacés par des champignons bien poêlés."}]$r$::jsonb, 'claude')
