insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin dauphinoi', 'Gratin dauphinois', array['gratin de pomme de terre', 'gratin dauphinoi maison']::text[], 'dish', $r$[{"title":"Gratin dauphinois","intro":"Des pommes de terre fondantes cuites lentement dans le lait et la crème, parfumées à l'ail.","minutes":80,"calories":420,"difficulty":"Facile","imageSearch":"potato gratin dauphinois","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité dauphinoise","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1200,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"crème fraîche liquide","plural":"crèmes fraîche liquide","qty":30,"unit":"cl","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C. Épluche les pommes de terre et coupe-les en fines rondelles, sans les laver.","timer":null},{"text":"Fais chauffer le lait, la crème et l'ail écrasé avec sel, poivre et muscade. Ajoute les pommes de terre et laisse frémir 10 min en remuant.","timer":{"label":"Frémissement","min":10}},{"text":"Beurre un plat à gratin et verse-y le tout.","timer":null},{"text":"Enfourne 1 h, jusqu'à ce que le dessus soit doré et que la pointe d'un couteau entre sans résistance.","timer":{"label":"Four","min":60}}],"kids":true,"variant":"La classique","change":""},{"title":"Gratin dauphinois léger","intro":"Le même fondant, avec seulement du lait : plus léger et toujours aussi bon.","minutes":80,"calories":300,"difficulty":"Facile","imageSearch":"light potato gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité dauphinoise","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1200,"unit":"g","have":false},{"name":"lait demi-écrémé","plural":"laits demi-écrémé","qty":80,"unit":"cl","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C. Coupe les pommes de terre épluchées en fines rondelles.","timer":null},{"text":"Fais frémir le lait avec l'ail écrasé, sel, poivre et muscade, ajoute les pommes de terre et laisse cuire 15 min.","timer":{"label":"Frémissement","min":15}},{"text":"Verse dans un plat à gratin.","timer":null},{"text":"Enfourne 1 h, jusqu'à ce que ce soit doré.","timer":{"label":"Four","min":60}}],"variant":"Plus léger","change":"La crème est remplacée par plus de lait, et le beurre disparaît."},{"title":"Gratin dauphinois au fromage","intro":"Le classique, avec un dessus doré et filant de comté.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"cheese potato gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1200,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"crème fraîche liquide","plural":"crèmes fraîche liquide","qty":30,"unit":"cl","have":false},{"name":"comté râpé","plural":"comté râpé","qty":100,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 160 °C. Coupe les pommes de terre épluchées en fines rondelles.","timer":null},{"text":"Fais frémir le lait, la crème et l'ail avec sel, poivre et muscade. Ajoute les pommes de terre et cuis 10 min.","timer":{"label":"Frémissement","min":10}},{"text":"Verse dans un plat et couvre de comté râpé.","timer":null},{"text":"Enfourne 1 h, jusqu'à ce que le fromage soit bien gratiné.","timer":{"label":"Four","min":60}}],"kids":true,"variant":"Gratiné au fromage","change":"Une couche de comté râpé gratine le dessus."}]$r$::jsonb, 'claude')
