insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('boeuf bourguignon', 'Bœuf bourguignon', array['bourguignon']::text[], 'dish', $r$[{"title":"Bœuf bourguignon","intro":"Le plat mijoté par excellence : du bœuf fondant au vin rouge, avec lardons, champignons et petits oignons.","minutes":210,"calories":650,"difficulty":"Moyen","imageSearch":"beef bourguignon stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité bourguignonne","serves":4,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":1200,"unit":"g","have":false},{"name":"vin rouge","plural":"vins rouge","qty":75,"unit":"cl","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le bœuf en gros cubes et fais-les dorer en plusieurs fois dans l'huile, dans une cocotte. Réserve.","timer":null},{"text":"Fais revenir les lardons, les oignons émincés et les carottes en rondelles 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Remets la viande, saupoudre de farine et mélange 1 min.","timer":null},{"text":"Verse le vin, ajoute l'ail, le bouquet garni, sel et poivre. Complète d'eau à hauteur.","timer":null},{"text":"Laisse mijoter à couvert et à feu doux 3 h.","timer":{"label":"Mijotage","min":180}},{"text":"Ajoute les champignons 30 min avant la fin. Sers avec des pommes de terre ou des pâtes.","timer":null}],"variant":"La classique","change":""},{"title":"Bœuf bourguignon express","intro":"Le goût du bourguignon pour un soir de semaine, grâce à l'autocuiseur.","minutes":75,"calories":620,"difficulty":"Facile","imageSearch":"quick beef stew red wine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité bourguignonne","serves":4,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":1000,"unit":"g","have":false},{"name":"vin rouge","plural":"vins rouge","qty":50,"unit":"cl","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le bœuf en cubes dans l'huile, directement dans l'autocuiseur, puis les lardons et les oignons.","timer":null},{"text":"Saupoudre de farine, mélange, puis ajoute le vin, les carottes en rondelles, le bouquet garni, sel et poivre.","timer":null},{"text":"Ferme et compte 45 min de cuisson après le chuchotement de la soupape.","timer":{"label":"Autocuiseur","min":45}},{"text":"Ouvre, ajoute les champignons émincés et laisse mijoter 10 min à découvert.","timer":{"label":"Cuisson","min":10}}],"variant":"Express","change":"Cuit à l'autocuiseur : 1 h au lieu de 3 h."},{"title":"Bourguignon de légumes","intro":"Une sauce au vin rouge riche et parfumée, pleine de champignons et de légumes fondants.","minutes":75,"calories":380,"difficulty":"Facile","imageSearch":"vegetable bourguignon mushrooms","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"champignon de Paris","plural":"champignons de Paris","qty":500,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":4,"unit":"","have":false},{"name":"panais","plural":"panais","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"vin rouge","plural":"vins rouge","qty":50,"unit":"cl","have":false},{"name":"concentré de tomate","plural":"concentré de tomate","qty":1,"unit":"c. à s.","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons émincés dans l'huile 5 min dans une cocotte.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les carottes et les panais en gros morceaux, puis les champignons coupés en deux. Fais dorer 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Saupoudre de farine, ajoute le concentré de tomate, puis le vin et 20 cl d'eau.","timer":null},{"text":"Ajoute le thym, sel et poivre, et laisse mijoter à couvert 45 min.","timer":{"label":"Mijotage","min":45}}],"variant":"Végétarienne","change":"Les champignons et les légumes racines remplacent la viande."}]$r$::jsonb, 'claude')
