insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pot au feu', 'Pot-au-feu', array[]::text[], 'dish', $r$[{"title":"Pot-au-feu","intro":"Le plat familial du dimanche : du bœuf longuement cuit dans un bouillon parfumé, avec ses légumes.","minutes":240,"calories":580,"difficulty":"Facile","imageSearch":"pot au feu beef vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"plat de côtes de bœuf","plural":"plats de côtes de bœuf","qty":800,"unit":"g","have":false},{"name":"paleron de bœuf","plural":"paleron de bœuf","qty":800,"unit":"g","have":false},{"name":"os à moelle","plural":"os à moelle","qty":4,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":6,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":3,"unit":"","have":false},{"name":"navet","plural":"navets","qty":4,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":8,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"clou de girofle","plural":"clous de girofle","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"gros sel","plural":"gros sel","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets la viande dans un grand faitout, couvre d'eau froide et porte à ébullition. Écume.","timer":null},{"text":"Ajoute l'oignon piqué des clous de girofle, le bouquet garni et le gros sel. Laisse frémir 2 h.","timer":{"label":"Frémissement","min":120}},{"text":"Ajoute les carottes, les poireaux et les navets coupés en tronçons, et les os à moelle. Cuis 45 min.","timer":{"label":"Cuisson","min":45}},{"text":"Fais cuire les pommes de terre à part 25 min dans un peu de bouillon.","timer":{"label":"Cuisson","min":25}},{"text":"Sers la viande et les légumes avec du gros sel, de la moutarde et des cornichons, et le bouillon à part.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pot-au-feu de poulet","intro":"La version plus légère et plus rapide, avec un poulet entier et ses légumes.","minutes":120,"calories":480,"difficulty":"Facile","imageSearch":"chicken pot au feu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet entier","plural":"poulets entiers","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":6,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":3,"unit":"","have":false},{"name":"navet","plural":"navets","qty":3,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":8,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"clou de girofle","plural":"clous de girofle","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"gros sel","plural":"gros sel","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets le poulet dans un faitout, couvre d'eau froide et porte à ébullition. Écume.","timer":null},{"text":"Ajoute l'oignon piqué des clous de girofle, le bouquet garni et le sel. Laisse frémir 45 min.","timer":{"label":"Frémissement","min":45}},{"text":"Ajoute les carottes, les poireaux, les navets et les pommes de terre. Cuis encore 40 min.","timer":{"label":"Cuisson","min":40}},{"text":"Découpe le poulet et sers-le avec les légumes et un peu de bouillon.","timer":null}],"kids":true,"variant":"Au poulet","change":"Une poule ou un poulet remplace le bœuf : c'est la poule au pot."},{"title":"Pot-au-feu à l'autocuiseur","intro":"Le vrai pot-au-feu, même en semaine.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"pressure cooker pot au feu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"plat de côtes de bœuf","plural":"plats de côtes de bœuf","qty":700,"unit":"g","have":false},{"name":"paleron de bœuf","plural":"paleron de bœuf","qty":700,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":5,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":2,"unit":"","have":false},{"name":"navet","plural":"navets","qty":3,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"gros sel","plural":"gros sel","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets la viande dans l'autocuiseur avec l'oignon, le bouquet garni et le sel. Couvre d'eau et écume à l'ébullition.","timer":null},{"text":"Ferme et compte 40 min après le chuchotement de la soupape.","timer":{"label":"Autocuiseur","min":40}},{"text":"Ouvre, ajoute tous les légumes en gros morceaux, referme et compte 15 min.","timer":{"label":"Autocuiseur","min":15}},{"text":"Sers avec moutarde et cornichons.","timer":null}],"kids":true,"variant":"Express","change":"À l'autocuiseur, la viande est prête en 1 h au lieu de 3."}]$r$::jsonb, 'claude')
