insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('hachi parmentier', 'Hachis parmentier', array['parmentier', 'hachi']::text[], 'dish', $r$[{"title":"Hachis parmentier","intro":"Une purée maison bien dorée sur une viande hachée parfumée : le réconfort assuré.","minutes":60,"calories":620,"difficulty":"Facile","imageSearch":"shepherds pie beef mash","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":60,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre épluchées 20 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais revenir les oignons émincés et l'ail, puis la viande 8 min. Sale, poivre et ajoute le persil.","timer":{"label":"Poêle","min":8}},{"text":"Écrase les pommes de terre avec le beurre et le lait chaud pour faire une purée.","timer":null},{"text":"Préchauffe le four à 200 °C. Mets la viande dans un plat, couvre de purée et parsème d'emmental.","timer":null},{"text":"Enfourne 20 min, jusqu'à ce que le dessus soit doré.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"La classique","change":""},{"title":"Hachis parmentier de patate douce","intro":"Une purée orangée et légèrement sucrée sur la viande hachée : les enfants adorent.","minutes":60,"calories":560,"difficulty":"Facile","imageSearch":"sweet potato shepherds pie","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":600,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":400,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les patates douces et les pommes de terre épluchées 20 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais revenir les oignons puis la viande 8 min, sale et poivre.","timer":{"label":"Poêle","min":8}},{"text":"Écrase les légumes avec le beurre et le lait.","timer":null},{"text":"Préchauffe le four à 200 °C. Mets la viande dans un plat, couvre de purée et d'emmental.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Patate douce","change":"La purée est faite avec moitié patate douce, plus douce et plus colorée."},{"title":"Hachis parmentier végétarien aux lentilles","intro":"Des lentilles mijotées avec carottes et tomate, sous une purée gratinée.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"lentil shepherds pie vegetarian","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"concentré de tomate","plural":"concentré de tomate","qty":2,"unit":"c. à s.","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min dans l'eau non salée.","timer":{"label":"Cuisson","min":25}},{"text":"Fais cuire les pommes de terre épluchées 20 min dans l'eau salée, puis écrase-les avec le beurre et le lait.","timer":{"label":"Cuisson","min":20}},{"text":"Fais revenir l'oignon et les carottes en petits dés 10 min, ajoute les lentilles égouttées et le concentré de tomate.","timer":{"label":"Poêle","min":10}},{"text":"Préchauffe le four à 200 °C. Mets les lentilles dans un plat, couvre de purée et d'emmental.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"Végétarienne","change":"Les lentilles et les carottes remplacent la viande hachée."}]$r$::jsonb, 'claude')
