insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quiche lorraine', 'Quiche lorraine', array['quiche']::text[], 'dish', $r$[{"title":"Quiche lorraine","intro":"La vraie quiche lorraine : une pâte croustillante, des lardons et un appareil crémeux aux œufs.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quiche lorraine","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité lorraine","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule et pique le fond.","timer":null},{"text":"Fais revenir les lardons 5 min à la poêle, sans matière grasse, et répartis-les sur la pâte.","timer":{"label":"Poêle","min":5}},{"text":"Bats les œufs avec la crème, le lait, un peu de sel, du poivre et la muscade.","timer":null},{"text":"Verse sur les lardons et enfourne 35 min, jusqu'à ce que ce soit doré.","timer":{"label":"Four","min":35}}],"kids":true,"variant":"La classique","change":""},{"title":"Quiche lorraine légère","intro":"Tout le goût de la quiche, avec un appareil plus léger.","minutes":50,"calories":420,"difficulty":"Facile","imageSearch":"light ham quiche","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"lait demi-écrémé","plural":"laits demi-écrémé","qty":40,"unit":"cl","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule et pique le fond.","timer":null},{"text":"Répartis les dés de jambon sur la pâte.","timer":null},{"text":"Bats les œufs avec le lait, la muscade, sel et poivre.","timer":null},{"text":"Verse et enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"Plus légère","change":"La crème est remplacée par du lait et les lardons par du jambon."},{"title":"Quiche aux poireaux et au chèvre","intro":"Une quiche douce et parfumée, avec des poireaux fondants et du chèvre.","minutes":55,"calories":500,"difficulty":"Facile","imageSearch":"leek goat cheese quiche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":2,"unit":"","have":false},{"name":"bûche de chèvre","plural":"bûches de chèvre","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule.","timer":null},{"text":"Émince les poireaux et fais-les fondre 10 min dans le beurre.","timer":{"label":"Poêle","min":10}},{"text":"Bats les œufs avec la crème, le lait, sel et poivre.","timer":null},{"text":"Répartis les poireaux sur la pâte, verse l'appareil et ajoute le chèvre en rondelles.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"Végétarienne","change":"Les lardons sont remplacés par des poireaux fondus et du chèvre."}]$r$::jsonb, 'claude')
