insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('croque monsieur', 'Croque-monsieur', array['croque']::text[], 'dish', $r$[{"title":"Croque-monsieur","intro":"Le croque doré et fondant, avec du jambon, de l'emmental et une touche de béchamel.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"croque monsieur ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais une petite béchamel : fais fondre 15 g de beurre, ajoute la farine, puis le lait en fouettant 3 min.","timer":{"label":"Béchamel","min":3}},{"text":"Préchauffe le four à 220 °C. Beurre légèrement les tranches de pain à l'extérieur.","timer":null},{"text":"Garnis 4 tranches de béchamel, de jambon et d'emmental, puis couvre avec les autres tranches.","timer":null},{"text":"Ajoute un peu de béchamel et d'emmental sur le dessus.","timer":null},{"text":"Enfourne 10 min, jusqu'à ce que ce soit bien doré.","timer":{"label":"Four","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Croque-madame","intro":"Le croque-monsieur, coiffé d'un œuf au plat coulant.","minutes":25,"calories":540,"difficulty":"Facile","imageSearch":"croque madame egg","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C. Beurre les tranches de pain à l'extérieur.","timer":null},{"text":"Garnis 4 tranches de jambon et d'emmental, couvre avec les autres et parsème d'emmental.","timer":null},{"text":"Enfourne 10 min.","timer":{"label":"Four","min":10}},{"text":"Pendant ce temps, fais cuire les œufs au plat 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Pose un œuf sur chaque croque et sers.","timer":null}],"kids":true,"variant":"Avec un œuf","change":"Un œuf au plat est posé sur le croque."},{"title":"Croque-monsieur végétarien","intro":"Un croque gourmand aux champignons, à la tomate et à l'emmental.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"vegetarian toasted sandwich mushroom","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les champignons émincés 5 min dans un peu de beurre.","timer":{"label":"Poêle","min":5}},{"text":"Préchauffe le four à 220 °C. Beurre les tranches de pain à l'extérieur.","timer":null},{"text":"Garnis 4 tranches de champignons, de rondelles de tomate et d'emmental, puis couvre.","timer":null},{"text":"Parsème d'emmental et enfourne 10 min.","timer":{"label":"Four","min":10}}],"kids":true,"variant":"Végétarienne","change":"Le jambon est remplacé par de la tomate et des champignons."}]$r$::jsonb, 'claude')
