insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('coq au vin', 'Coq au vin', array['poulet au vin']::text[], 'dish', $r$[{"title":"Coq au vin","intro":"Le grand classique mijoté : du poulet fondant dans une sauce au vin rouge, lardons et champignons.","minutes":120,"calories":620,"difficulty":"Moyen","imageSearch":"coq au vin chicken red wine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet en morceaux","plural":"poulets en morceaux","qty":1,"unit":"","have":false},{"name":"vin rouge","plural":"vins rouge","qty":75,"unit":"cl","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les morceaux de poulet dans l'huile dans une cocotte. Réserve.","timer":null},{"text":"Fais revenir les lardons, les oignons et les carottes 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Remets le poulet, saupoudre de farine et mélange.","timer":null},{"text":"Verse le vin, ajoute l'ail, le bouquet garni, sel et poivre. Laisse mijoter 1 h 15 à couvert.","timer":{"label":"Mijotage","min":75}},{"text":"Ajoute les champignons et cuis encore 20 min.","timer":{"label":"Cuisson","min":20}}],"variant":"La classique","change":""},{"title":"Coq au vin blanc","intro":"Une version plus douce, au vin blanc, avec une sauce crémeuse.","minutes":90,"calories":580,"difficulty":"Moyen","imageSearch":"chicken white wine cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet en morceaux","plural":"poulets en morceaux","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":50,"unit":"cl","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet dans l'huile dans une cocotte, puis les lardons et les oignons.","timer":null},{"text":"Verse le vin blanc, ajoute le thym, sel et poivre. Laisse mijoter 50 min à couvert.","timer":{"label":"Mijotage","min":50}},{"text":"Ajoute les champignons émincés et cuis 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute la crème et laisse réduire 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Au vin blanc","change":"Le vin rouge est remplacé par du vin blanc et un peu de crème."},{"title":"Coq au vin express","intro":"Le goût du coq au vin, en semaine.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quick chicken red wine stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":8,"unit":"","have":false},{"name":"vin rouge","plural":"vins rouge","qty":40,"unit":"cl","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet dans l'huile 8 min, puis les lardons et l'oignon émincé.","timer":{"label":"Cuisson","min":8}},{"text":"Saupoudre de farine, verse le vin, sale et poivre.","timer":null},{"text":"Ajoute les champignons et laisse mijoter 30 min à couvert.","timer":{"label":"Mijotage","min":30}}],"variant":"Express","change":"Avec des hauts de cuisse désossés, c'est prêt en moins d'une heure."}]$r$::jsonb, 'claude')
