insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet basquaise', 'Poulet basquaise', array['basquaise']::text[], 'dish', $r$[{"title":"Poulet basquaise","intro":"Du poulet mijoté avec poivrons, tomates et piment d'Espelette : le soleil du Pays basque.","minutes":70,"calories":480,"difficulty":"Facile","imageSearch":"basque chicken peppers","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"poulet en morceaux","plural":"poulets en morceaux","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les morceaux de poulet dans l'huile dans une cocotte. Réserve.","timer":null},{"text":"Fais revenir les oignons, l'ail et les poivrons en lanières 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les tomates en morceaux, le vin, le piment, sel et poivre.","timer":null},{"text":"Remets le poulet et laisse mijoter 45 min à couvert.","timer":{"label":"Mijotage","min":45}}],"kids":true,"variant":"La classique","change":""},{"title":"Poulet basquaise express","intro":"Les saveurs du basquaise, pour un soir pressé.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"quick chicken peppers tomato","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet en morceaux et fais-le dorer 5 min dans l'huile.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute l'oignon, l'ail et les poivrons en lanières, cuis 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Verse les tomates, ajoute le piment, sel et poivre, et laisse mijoter 15 min.","timer":{"label":"Mijotage","min":15}}],"kids":true,"variant":"Express","change":"Des blancs de poulet et des tomates en boîte : c'est prêt en 30 minutes."},{"title":"Basquaise de légumes et pois chiches","intro":"La piperade mijotée et des pois chiches fondants, pour un plat végé plein de soleil.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"basque peppers chickpeas stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"pois chiche","plural":"pois chiches","qty":400,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, l'ail et les poivrons en lanières dans l'huile 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les tomates en morceaux, le piment, sel et poivre, et laisse mijoter 15 min.","timer":{"label":"Mijotage","min":15}},{"text":"Ajoute les pois chiches égouttés et cuis encore 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarienne","change":"Le poulet est remplacé par des pois chiches."}]$r$::jsonb, 'claude')
