insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet roti', 'Poulet rôti', array['poulet au four', 'poulet roti du dimanche']::text[], 'dish', $r$[{"title":"Poulet rôti","intro":"Un poulet doré et croustillant, avec un jus maison et des pommes de terre rôties.","minutes":90,"calories":620,"difficulty":"Facile","imageSearch":"roast chicken potatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet entier","plural":"poulets entiers","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":4,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C. Sors le poulet du réfrigérateur 30 min avant.","timer":null},{"text":"Frotte le poulet avec le beurre mou, sel, poivre et thym. Mets l'ail à l'intérieur.","timer":null},{"text":"Pose-le dans un plat, entouré des pommes de terre en morceaux arrosées d'huile.","timer":null},{"text":"Verse un verre d'eau dans le plat et enfourne 1 h 15, en arrosant toutes les 20 min.","timer":{"label":"Four","min":75}},{"text":"Laisse reposer 10 min sous une feuille d'alu avant de découper.","timer":{"label":"Repos","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Poulet rôti au citron et aux herbes","intro":"Un poulet rôti plein de fraîcheur, au citron et au romarin.","minutes":90,"calories":580,"difficulty":"Facile","imageSearch":"lemon herb roast chicken","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poulet entier","plural":"poulets entiers","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":4,"unit":"gousse","have":false},{"name":"romarin","plural":"romarin","qty":null,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C.","timer":null},{"text":"Glisse un citron coupé en quatre, l'ail et le romarin dans le poulet. Frotte-le d'huile, sel et poivre.","timer":null},{"text":"Entoure-le des pommes de terre et de l'autre citron en quartiers.","timer":null},{"text":"Enfourne 1 h 15 en arrosant régulièrement.","timer":{"label":"Four","min":75}},{"text":"Laisse reposer 10 min avant de servir.","timer":{"label":"Repos","min":10}}],"variant":"Citron et herbes","change":"Le poulet est parfumé au citron, à l'ail et au romarin."},{"title":"Cuisses de poulet rôties","intro":"Le goût du poulet du dimanche, en 45 minutes.","minutes":45,"calories":560,"difficulty":"Facile","imageSearch":"roasted chicken legs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C.","timer":null},{"text":"Mélange l'huile, le paprika, le thym, sel et poivre, et badigeonne les cuisses.","timer":null},{"text":"Mets-les dans un plat avec les pommes de terre en quartiers et l'ail.","timer":null},{"text":"Enfourne 40 min, jusqu'à ce que la peau soit bien croustillante.","timer":{"label":"Four","min":40}}],"kids":true,"variant":"Express","change":"Des cuisses au lieu du poulet entier : cuisson deux fois plus courte."}]$r$::jsonb, 'claude')
