insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('ratatouille', 'Ratatouille', array['ratatouille nicoise']::text[], 'dish', $r$[{"title":"Ratatouille","intro":"Les légumes du soleil mijotés doucement à l'huile d'olive et aux herbes de Provence.","minutes":75,"calories":220,"difficulty":"Facile","imageSearch":"ratatouille provencal vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spécialité niçoise","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"poivron jaune","plural":"poivrons jaunes","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"herbes de Provence","plural":"herbes de Provence","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe tous les légumes en dés de même taille.","timer":null},{"text":"Fais revenir les oignons et l'ail 5 min dans l'huile, dans une cocotte.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les poivrons et les aubergines, cuis 10 min en remuant.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les courgettes, les tomates, les herbes, sel et poivre.","timer":null},{"text":"Laisse mijoter 45 min à couvert, puis 10 min à découvert pour réduire.","timer":{"label":"Mijotage","min":55}}],"variant":"La classique","change":""},{"title":"Ratatouille au four","intro":"Des légumes rôtis et caramélisés, avec presque rien à faire.","minutes":60,"calories":230,"difficulty":"Facile","imageSearch":"roasted ratatouille vegetables tray","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":250,"unit":"g","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"herbes de Provence","plural":"herbes de Provence","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les légumes en gros morceaux et mets-les sur une plaque avec l'ail et les tomates cerises.","timer":null},{"text":"Arrose d'huile, ajoute les herbes, sel et poivre, et mélange.","timer":null},{"text":"Enfourne 45 min en remuant à mi-cuisson.","timer":{"label":"Four","min":45}}],"variant":"Au four","change":"Les légumes rôtissent au four au lieu de mijoter."},{"title":"Tian provençal","intro":"La ratatouille en version élégante : des rondelles de légumes confites au four.","minutes":75,"calories":210,"difficulty":"Facile","imageSearch":"tian provencal vegetables","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité provençale","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Fais fondre les oignons émincés 10 min dans 1 c. à s. d'huile et étale-les au fond d'un plat.","timer":{"label":"Poêle","min":10}},{"text":"Coupe l'aubergine, les courgettes et les tomates en rondelles fines.","timer":null},{"text":"Range-les en les alternant debout dans le plat.","timer":null},{"text":"Arrose d'huile, ajoute l'ail haché, le thym, sel et poivre.","timer":null},{"text":"Enfourne 1 h, couvert d'alu les 30 premières minutes.","timer":{"label":"Four","min":60}}],"variant":"Tian","change":"Les légumes sont coupés en rondelles et rangés en rosace avant d'aller au four."}]$r$::jsonb, 'claude')
