insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin de courgette', 'Gratin de courgettes', array['gratin courgette']::text[], 'dish', $r$[{"title":"Gratin de courgettes","intro":"Des courgettes fondantes dans un appareil crémeux, gratinées à l'emmental.","minutes":40,"calories":320,"difficulty":"Facile","imageSearch":"zucchini gratin cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en rondelles.","timer":null},{"text":"Fais-les revenir 8 min à la poêle avec l'huile et l'ail.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec la crème, la moitié de l'emmental, sel et poivre.","timer":null},{"text":"Mets les courgettes dans un plat, verse l'appareil et parsème du reste d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"La classique","change":""},{"title":"Gratin de courgettes léger","intro":"Le gratin de courgettes en version légère, toujours bien doré.","minutes":40,"calories":220,"difficulty":"Facile","imageSearch":"light zucchini bake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromages blanc","qty":150,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":10,"unit":"cl","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en rondelles et fais-les revenir 8 min sans matière grasse.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec le fromage blanc, le lait, sel et poivre.","timer":null},{"text":"Mets les courgettes dans un plat, verse l'appareil et parsème de parmesan.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Plus léger","change":"La crème est remplacée par du lait et du fromage blanc."},{"title":"Gratin de courgettes au chèvre","intro":"Un gratin parfumé au chèvre fondu et au thym.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"zucchini goat cheese gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"bûche de chèvre","plural":"bûches de chèvre","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en rondelles et fais-les revenir 8 min dans l'huile.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec la crème, le thym, sel et poivre.","timer":null},{"text":"Mets les courgettes dans un plat, verse l'appareil et dépose le chèvre en rondelles.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Au chèvre","change":"Le chèvre remplace l'emmental, avec du thym."}]$r$::jsonb, 'claude')
