insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('soupe a l oignon', 'Soupe à l''oignon', array['soupe a l oignon gratinee', 'gratinee']::text[], 'dish', $r$[{"title":"Soupe à l'oignon gratinée","intro":"Des oignons longuement caramélisés dans un bouillon, sous un croûton gratiné au fromage.","minutes":70,"calories":420,"difficulty":"Facile","imageSearch":"french onion soup","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"oignon","plural":"oignons","qty":6,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":0.5,"unit":"","have":false},{"name":"gruyère râpé","plural":"gruyère râpé","qty":100,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Émince finement les oignons et fais-les fondre dans le beurre 30 min à feu doux, jusqu'à ce qu'ils soient bien dorés.","timer":{"label":"Cuisson","min":30}},{"text":"Saupoudre de farine, mélange, puis verse le vin blanc et 1,2 l d'eau avec le bouillon.","timer":null},{"text":"Laisse mijoter 20 min, sale et poivre.","timer":{"label":"Mijotage","min":20}},{"text":"Verse dans des bols, pose des tranches de pain grillé et couvre de gruyère.","timer":null},{"text":"Passe 5 min sous le gril du four.","timer":{"label":"Gril","min":5}}],"variant":"La classique","change":""},{"title":"Soupe à l'oignon légère","intro":"Toute la douceur des oignons caramélisés, en soupe légère.","minutes":60,"calories":180,"difficulty":"Facile","imageSearch":"light onion soup bowl","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"oignon","plural":"oignons","qty":6,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Émince les oignons et fais-les dorer 30 min dans l'huile à feu doux.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute 1,2 l d'eau, le bouillon et le thym.","timer":null},{"text":"Laisse mijoter 20 min, sale et poivre.","timer":{"label":"Mijotage","min":20}}],"variant":"Plus légère","change":"Sans croûton gratiné, et avec moins de beurre."},{"title":"Soupe à l'oignon au cidre","intro":"Une soupe à l'oignon douce et fruitée, gratinée au camembert.","minutes":70,"calories":440,"difficulty":"Facile","imageSearch":"onion soup cider","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité normande","serves":4,"items":[{"name":"oignon","plural":"oignons","qty":6,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"cidre brut","plural":"cidre brut","qty":25,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":0.5,"unit":"","have":false},{"name":"camembert","plural":"camemberts","qty":0.5,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre les oignons émincés 30 min dans le beurre à feu doux.","timer":{"label":"Cuisson","min":30}},{"text":"Verse le cidre, laisse réduire 5 min, puis ajoute 1 l d'eau et le bouillon.","timer":{"label":"Cuisson","min":5}},{"text":"Laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Verse dans des bols, ajoute du pain grillé et des tranches de camembert, et passe 5 min sous le gril.","timer":{"label":"Gril","min":5}}],"variant":"Au cidre","change":"Le vin blanc est remplacé par du cidre, à la normande."}]$r$::jsonb, 'claude')
