insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('veloute de potiron', 'Velouté de potiron', array['soupe de potiron', 'veloute de citrouille', 'soupe de citrouille', 'veloute de courge']::text[], 'dish', $r$[{"title":"Velouté de potiron","intro":"Un velouté orange et onctueux, tout doux, avec une touche de crème.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"pumpkin soup bowl","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potiron","plural":"potirons","qty":1000,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Épluche le potiron et la pomme de terre et coupe-les en cubes.","timer":null},{"text":"Fais revenir l'oignon dans le beurre 3 min dans une casserole.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute les légumes, couvre d'eau avec le bouillon et laisse cuire 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Mixe en ajoutant la crème, la muscade, sel et poivre.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Velouté de potiron au lait de coco","intro":"Un velouté doux et exotique, au lait de coco et au curry.","minutes":40,"calories":240,"difficulty":"Facile","imageSearch":"pumpkin coconut curry soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potiron","plural":"potirons","qty":1000,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"curry","plural":"curry","qty":1,"unit":"c. à c.","have":false},{"name":"gingembre","plural":"gingembre","qty":null,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans l'huile avec le curry et un peu de gingembre râpé 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute le potiron en cubes, couvre d'eau avec le bouillon et cuis 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Mixe avec le lait de coco et sale.","timer":null}],"variant":"Au lait de coco","change":"Le lait de coco et un peu de curry remplacent la crème."},{"title":"Velouté de potiron et châtaignes","intro":"Le velouté d'automne, avec des châtaignes pour plus de douceur.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"pumpkin chestnut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potiron","plural":"potirons","qty":800,"unit":"g","have":false},{"name":"châtaigne cuite","plural":"châtaignes cuites","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans le beurre 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute le potiron en cubes et les châtaignes, couvre d'eau avec le bouillon et cuis 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Mixe avec la crème, sale et poivre.","timer":null}],"variant":"Aux châtaignes","change":"Des châtaignes cuites donnent un goût de fête et une texture plus riche."}]$r$::jsonb, 'claude')
