insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('cassoulet', 'Cassoulet', array['cassoulet maison']::text[], 'dish', $r$[{"title":"Cassoulet","intro":"Haricots blancs fondants, saucisse de Toulouse et confit de canard, gratinés au four.","minutes":180,"calories":850,"difficulty":"Moyen","imageSearch":"cassoulet beans sausage duck","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Sud-Ouest","serves":4,"items":[{"name":"haricot blanc sec","plural":"haricots blancs secs","qty":500,"unit":"g","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"cuisse de canard confite","plural":"cuisses de canard confites","qty":2,"unit":"","have":false},{"name":"poitrine fumée","plural":"poitrine fumée","qty":150,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":4,"unit":"gousse","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"La veille, fais tremper les haricots dans l'eau froide.","timer":null},{"text":"Fais cuire les haricots 1 h dans l'eau avec la carotte, l'oignon et le bouquet garni.","timer":{"label":"Cuisson","min":60}},{"text":"Fais dorer la poitrine en dés, les saucisses et le canard dans une poêle.","timer":null},{"text":"Préchauffe le four à 160 °C. Dans un plat, mélange les haricots égouttés, les tomates, l'ail et les viandes, et ajoute un peu d'eau de cuisson.","timer":null},{"text":"Saupoudre de chapelure et enfourne 1 h 30, en cassant la croûte deux fois.","timer":{"label":"Four","min":90}}],"variant":"La classique","change":""},{"title":"Cassoulet express","intro":"Le goût du cassoulet sans y passer la journée.","minutes":45,"calories":780,"difficulty":"Facile","imageSearch":"quick cassoulet beans","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Sud-Ouest","serves":4,"items":[{"name":"haricot blanc","plural":"haricots blancs","qty":800,"unit":"g","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"chapelure","plural":"chapelure","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais dorer les saucisses coupées en tronçons, les lardons et l'oignon 10 min.","timer":{"label":"Poêle","min":10}},{"text":"Ajoute les haricots égouttés, les tomates et l'ail, sale et poivre.","timer":null},{"text":"Verse dans un plat, saupoudre de chapelure et enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Express","change":"Avec des haricots en conserve, c'est prêt en 45 minutes."},{"title":"Cassoulet végétarien","intro":"Des haricots mijotés à la tomate et au paprika fumé, gratinés comme un vrai.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"vegetarian bean cassoulet","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"haricot blanc","plural":"haricots blancs","qty":800,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"paprika fumé","plural":"paprika fumé","qty":1,"unit":"c. à c.","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais revenir l'oignon, le poireau et les carottes en dés 10 min dans l'huile.","timer":{"label":"Poêle","min":10}},{"text":"Ajoute les haricots, les tomates, l'ail, le paprika, sel et poivre, et laisse mijoter 10 min.","timer":{"label":"Mijotage","min":10}},{"text":"Verse dans un plat, couvre de chapelure et enfourne 30 min.","timer":{"label":"Four","min":30}}],"variant":"Végétarienne","change":"La viande est remplacée par des légumes et de la fumée de paprika."}]$r$::jsonb, 'claude')
