insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('choucroute', 'Choucroute', array['choucroute garnie']::text[], 'dish', $r$[{"title":"Choucroute garnie","intro":"Le chou fermenté mijoté au vin blanc, avec saucisses, lard et pommes de terre.","minutes":120,"calories":780,"difficulty":"Facile","imageSearch":"choucroute sauerkraut sausages","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"choucroute crue","plural":"choucroute crue","qty":1200,"unit":"g","have":false},{"name":"saucisse de Strasbourg","plural":"saucisses de Strasbourg","qty":4,"unit":"","have":false},{"name":"saucisse de Montbéliard","plural":"saucisses de Montbéliard","qty":2,"unit":"","have":false},{"name":"lard fumé","plural":"lard fumé","qty":300,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":8,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":25,"unit":"cl","have":false},{"name":"baie de genièvre","plural":"baies de genièvre","qty":6,"unit":"","have":false},{"name":"saindoux","plural":"saindoux","qty":1,"unit":"c. à s.","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Rince la choucroute et égoutte-la bien.","timer":null},{"text":"Fais revenir l'oignon dans le saindoux, ajoute la choucroute, le genièvre, le vin et 25 cl d'eau.","timer":null},{"text":"Ajoute le lard et laisse mijoter 1 h à couvert.","timer":{"label":"Mijotage","min":60}},{"text":"Ajoute les saucisses de Montbéliard et les pommes de terre épluchées, cuis 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les saucisses de Strasbourg 10 min avant la fin.","timer":{"label":"Cuisson","min":10}}],"variant":"La classique","change":""},{"title":"Choucroute de la mer","intro":"Une choucroute légère au saumon, au cabillaud et aux crevettes.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"fish sauerkraut","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"choucroute cuite","plural":"choucroute cuite","qty":1000,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":2,"unit":"","have":false},{"name":"crevette","plural":"crevettes","qty":8,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":20,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais chauffer la choucroute avec le vin blanc 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les pommes de terre à la vapeur 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Pose les poissons et les crevettes sur la choucroute et cuis 10 min à couvert.","timer":{"label":"Cuisson","min":10}},{"text":"Fais chauffer la crème avec le beurre et un peu de jus de cuisson, et nappe le poisson.","timer":null}],"variant":"De la mer","change":"Les charcuteries sont remplacées par des poissons."},{"title":"Choucroute express","intro":"La choucroute pour un soir de semaine.","minutes":35,"calories":700,"difficulty":"Facile","imageSearch":"quick sauerkraut sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"choucroute cuite","plural":"choucroute cuite","qty":1000,"unit":"g","have":false},{"name":"saucisse de Strasbourg","plural":"saucisses de Strasbourg","qty":4,"unit":"","have":false},{"name":"saucisse fumée","plural":"saucisses fumées","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":15,"unit":"cl","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais chauffer la choucroute avec le vin blanc et les saucisses fumées 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les saucisses de Strasbourg 8 min avant la fin et sers avec les pommes de terre.","timer":{"label":"Cuisson","min":8}}],"variant":"Express","change":"Avec une choucroute déjà cuite, c'est prêt en 35 minutes."}]$r$::jsonb, 'claude')
