insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('roti de porc', 'Rôti de porc', array['roti de porc au four', 'roti de porc moutarde']::text[], 'dish', $r$[{"title":"Rôti de porc","intro":"Un rôti tendre et doré, avec son jus et des pommes de terre fondantes.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"roast pork loin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Frotte le rôti d'huile, de sel, de poivre et de thym, et fais-le dorer sur toutes les faces dans une cocotte.","timer":null},{"text":"Ajoute les oignons en quartiers, l'ail, les pommes de terre en morceaux et un verre d'eau.","timer":null},{"text":"Enfourne 1 h, en arrosant de jus deux fois.","timer":{"label":"Four","min":60}},{"text":"Laisse reposer 10 min avant de trancher.","timer":{"label":"Repos","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Rôti de porc à la moutarde","intro":"Un rôti tout doux, avec une sauce moutarde à la crème.","minutes":80,"calories":580,"difficulty":"Facile","imageSearch":"pork roast mustard sauce","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"moutarde","plural":"moutarde","qty":3,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Badigeonne le rôti de 2 c. à s. de moutarde, sale et poivre.","timer":null},{"text":"Mets-le dans un plat avec l'oignon émincé, le vin et un filet d'huile. Enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Verse le jus dans une casserole avec la crème et le reste de moutarde, et laisse épaissir 3 min.","timer":{"label":"Sauce","min":3}}],"kids":true,"variant":"À la moutarde","change":"Le rôti est enrobé de moutarde et servi avec une sauce crémeuse."},{"title":"Rôti de porc au miel et aux épices","intro":"Un rôti laqué, sucré-salé et parfumé.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"honey glazed pork roast","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"miel","plural":"miel","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"quatre-épices","plural":"quatre-épices","qty":1,"unit":"c. à c.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Mélange le miel, la sauce soja, l'ail haché et les épices.","timer":null},{"text":"Mets le rôti dans un plat avec les pommes de terre en morceaux et badigeonne-le de sauce.","timer":null},{"text":"Enfourne 1 h en arrosant toutes les 20 min.","timer":{"label":"Four","min":60}}],"variant":"Miel et épices","change":"Un glaçage au miel, au soja et aux épices caramélise le rôti."}]$r$::jsonb, 'claude')
