insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('lapin a la moutarde', 'Lapin à la moutarde', array['lapin moutarde', 'lapin']::text[], 'dish', $r$[{"title":"Lapin à la moutarde","intro":"Un lapin tendre, mijoté dans une sauce crémeuse à la moutarde.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"rabbit mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lapin en morceaux","plural":"lapins en morceaux","qty":1,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":4,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"vin blanc","plural":"vins blanc","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":3,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Badigeonne les morceaux de lapin avec la moutarde.","timer":null},{"text":"Fais-les dorer dans le beurre dans une cocotte, avec les échalotes émincées.","timer":null},{"text":"Verse le vin blanc, ajoute le thym, sel et poivre, et laisse mijoter 50 min à couvert.","timer":{"label":"Mijotage","min":50}},{"text":"Ajoute la crème et laisse réduire 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"La classique","change":""},{"title":"Lapin aux pruneaux","intro":"Le lapin à la flamande, fondant et doucement sucré.","minutes":80,"calories":540,"difficulty":"Moyen","imageSearch":"rabbit prunes stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lapin en morceaux","plural":"lapins en morceaux","qty":1,"unit":"","have":false},{"name":"pruneau","plural":"pruneaux","qty":16,"unit":"","have":false},{"name":"bière blonde","plural":"bière blonde","qty":33,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le lapin dans le beurre avec les oignons émincés.","timer":null},{"text":"Saupoudre de farine, ajoute la bière et la moutarde, sale et poivre.","timer":null},{"text":"Laisse mijoter 40 min, ajoute les pruneaux et cuis encore 20 min.","timer":{"label":"Mijotage","min":60}}],"variant":"Aux pruneaux","change":"Des pruneaux et un peu de bière donnent une sauce sucrée-salée."},{"title":"Poulet à la moutarde","intro":"Toute la sauce du lapin à la moutarde, avec du poulet.","minutes":45,"calories":500,"difficulty":"Facile","imageSearch":"chicken mustard cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":8,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":3,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet dans le beurre 10 min avec les échalotes.","timer":{"label":"Cuisson","min":10}},{"text":"Verse le vin, couvre et laisse cuire 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Ajoute la crème et la moutarde, et laisse épaissir 5 min.","timer":{"label":"Cuisson","min":5}}],"kids":true,"variant":"Au poulet","change":"Le lapin est remplacé par des hauts de cuisse de poulet."}]$r$::jsonb, 'claude')
