insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet a la creme', 'Poulet à la crème', array['poulet a la creme et champignon', 'emince de poulet a la creme', 'poulet creme champignon']::text[], 'dish', $r$[{"title":"Poulet à la crème et aux champignons","intro":"Des morceaux de poulet tendres dans une sauce crémeuse aux champignons.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"chicken mushroom cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet en morceaux et fais-le dorer 6 min dans le beurre. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir les échalotes et les champignons émincés 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Remets le poulet, ajoute la crème, sale et poivre, et laisse mijoter 5 min.","timer":{"label":"Mijotage","min":5}},{"text":"Parsème de persil et sers avec du riz ou des pâtes.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Poulet à la crème légère","intro":"La même sauce douce, en plus léger.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"light creamy chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"crème légère","plural":"crème légère","qty":20,"unit":"cl","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":1,"unit":"","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en morceaux 6 min dans l'huile.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les échalotes et les champignons et cuis 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Verse 10 cl d'eau avec le bouillon émietté et la crème, et laisse épaissir 5 min.","timer":{"label":"Mijotage","min":5}}],"kids":true,"variant":"Plus légère","change":"La crème est remplacée par de la crème légère et un peu de bouillon."},{"title":"Poulet à la crème et à la moutarde","intro":"Le poulet à la crème, relevé à la moutarde à l'ancienne.","minutes":25,"calories":540,"difficulty":"Facile","imageSearch":"chicken creamy mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"moutarde à l'ancienne","plural":"moutarde à l'ancienne","qty":2,"unit":"c. à s.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en morceaux 6 min dans le beurre avec l'oignon émincé.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute la crème et la moutarde, sale et poivre.","timer":null},{"text":"Laisse mijoter 8 min.","timer":{"label":"Mijotage","min":8}}],"kids":true,"variant":"À la moutarde","change":"De la moutarde à l'ancienne relève la sauce."}]$r$::jsonb, 'claude')
