insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('endive au jambon', 'Endives au jambon', array['gratin d endive', 'endive jambon']::text[], 'dish', $r$[{"title":"Endives au jambon","intro":"Des endives fondantes roulées dans du jambon, gratinées sous une béchamel.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"endives ham gratin bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min à la vapeur ou dans l'eau, puis presse-les bien pour les égoutter.","timer":{"label":"Cuisson","min":20}},{"text":"Fais une béchamel : beurre fondu, farine, puis lait en fouettant 5 min. Ajoute muscade, sel et poivre.","timer":{"label":"Béchamel","min":5}},{"text":"Préchauffe le four à 200 °C. Roule chaque endive dans une tranche de jambon et range-les dans un plat.","timer":null},{"text":"Nappe de béchamel et parsème d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"La classique","change":""},{"title":"Endives au jambon légères","intro":"Le gratin réconfortant, en version plus légère.","minutes":55,"calories":330,"difficulty":"Facile","imageSearch":"light endive ham gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"lait demi-écrémé","plural":"laits demi-écrémé","qty":50,"unit":"cl","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":2,"unit":"c. à s.","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":40,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min à la vapeur et égoutte-les bien.","timer":{"label":"Cuisson","min":20}},{"text":"Délaye la fécule dans un peu de lait froid, ajoute le reste du lait et fais épaissir 3 min en remuant.","timer":{"label":"Sauce","min":3}},{"text":"Préchauffe le four à 200 °C. Roule les endives dans le jambon et range-les dans un plat.","timer":null},{"text":"Nappe de sauce, parsème d'emmental et enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"Plus légères","change":"La béchamel est faite au lait demi-écrémé, sans beurre."},{"title":"Endives au jambon et au maroilles","intro":"Le gratin d'endives avec le caractère du maroilles.","minutes":60,"calories":540,"difficulty":"Facile","imageSearch":"endive gratin strong cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"maroilles","plural":"maroilles","qty":0.5,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min et égoutte-les bien.","timer":{"label":"Cuisson","min":20}},{"text":"Prépare la béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Préchauffe le four à 200 °C. Roule les endives dans le jambon, range-les dans un plat et nappe de béchamel.","timer":null},{"text":"Ajoute le maroilles en tranches et enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Au maroilles","change":"Le maroilles remplace l'emmental, pour un gratin bien du Nord."}]$r$::jsonb, 'claude')
