mates concassées","qty":800,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, les carottes et la courgette en petits dés 8 min dans l'huile.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute la viande et fais-la dorer 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les tomates et l'ail, sale, poivre et laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}},{"text":"Fais cuire les spaghetti et sers avec le basilic.","timer":{"label":"Pâtes","min":10}}],"kids":true,"variant":"Plus légère","change":"Avec du bœuf à 5 % et plus de légumes."}]$r$::jsonb, 'claude')
