insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pate carbonara', 'Pâtes carbonara', array['carbonara', 'spaghetti carbonara']::text[], 'dish', $r$[{"title":"Spaghetti carbonara","intro":"La vraie carbonara : des œufs, du pecorino et du guanciale, sans crème.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"pecorino râpé","plural":"pecorino râpé","qty":60,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti dans l'eau bouillante salée.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer le guanciale en lamelles 5 min à la poêle, sans matière grasse.","timer":{"label":"Poêle","min":5}},{"text":"Bats les jaunes, l'œuf entier, le pecorino et beaucoup de poivre.","timer":null},{"text":"Égoutte les pâtes en gardant un peu d'eau de cuisson, et mets-les dans la poêle hors du feu.","timer":null},{"text":"Verse les œufs en mélangeant vite, avec un peu d'eau de cuisson pour obtenir une sauce crémeuse.","timer":null}],"variant":"La classique","change":""},{"title":"Pâtes carbonara à la française","intro":"La carbo crémeuse de chez nous, aux lardons et à la crème.","minutes":20,"calories":700,"difficulty":"Facile","imageSearch":"creamy carbonara bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":2,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":50,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais revenir les lardons et l'oignon émincé 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute la crème et laisse chauffer 2 min.","timer":{"label":"Cuisson","min":2}},{"text":"Mélange les pâtes égouttées avec la sauce, puis hors du feu avec les jaunes et le parmesan.","timer":null}],"kids":true,"variant":"À la française","change":"Avec des lardons et de la crème, comme on la fait souvent en France."},{"title":"Carbonara aux courgettes","intro":"Une carbonara toute verte et crémeuse, sans viande.","minutes":20,"calories":560,"difficulty":"Facile","imageSearch":"zucchini carbonara pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer les courgettes en petits dés avec l'ail dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Bats les jaunes, l'œuf, le parmesan et le poivre.","timer":null},{"text":"Mélange les pâtes avec les courgettes hors du feu, puis avec les œufs et un peu d'eau de cuisson.","timer":null}],"variant":"Végétarienne","change":"Les lardons sont remplacés par des courgettes bien dorées."}]$r$::jsonb, 'claude')
