:""},{"title":"Lasagnes aux légumes","intro":"Des lasagnes fondantes aux légumes du soleil.","minutes":80,"calories":520,"difficulty":"Moyen","imageSearch":"vegetable lasagna","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuille de lasagne","plural":"feuilles de lasagne","qty":12,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":2,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":60,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les légumes en petits dés dans l'huile 15 min, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":25}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Préchauffe le four à 180 °C. Alterne légumes, lasagnes et béchamel dans un plat.","timer":null},{"text":"Termine par la mozzarella en tranches et enfourne 40 min.","timer":{"label":"Four","min":40}}],"variant":"Végétarienne","change":"La viande est remplacée par des courgettes, des aubergines et des poivrons."},{"title":"Lasagnes saumon et épinards","intro":"Des lasagnes crémeuses au saumon et aux épinards.","minutes":70,"calories":600,"difficulty":"Moyen","imageSearch":"salmon spinach lasagna","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"feuille de lasagne","plural":"feuilles de lasagne","qty":12,"unit":"","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":3,"unit":"","have":false},{"name":"épinard","plural":"épinards","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":60,"unit":"cl","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":50,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais tomber les épinards 5 min à la poêle.","timer":{"label":"Poêle","min":5}},{"text":"Prépare une béchamel, ajoute la crème, sel et poivre.","timer":null},{"text":"Préchauffe le four à 180 °C. Coupe le saumon cru en petits dés.","timer":null},{"text":"Alterne lasagnes, épinards, saumon et béchamel dans un plat, puis parsème de parmesan.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"Saumon épinards","change":"Le bœuf est remplacé par du saumon et des épinards."}]$r$::jsonb, 'claude')
