,"have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":8,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Mixe les tomates séchées égouttées, les amandes, l'ail, le parmesan et l'huile.","timer":null},{"text":"Mélange avec les pâtes et un peu d'eau de cuisson.","timer":null}],"kids":true,"variant":"Pesto rouge","change":"Le basilic est remplacé par des tomates séchées."},{"title":"Pâtes au pesto, poulet et tomates cerises","intro":"Un plat complet et coloré, au pesto et au poulet.","minutes":25,"calories":620,"difficulty":"Facile","imageSearch":"pesto chicken pasta tomatoes","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":350,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":200,"unit":"g","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais dorer le poulet en dés 8 min dans l'huile.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute les tomates cerises coupées en deux 2 min.","timer":{"label":"Poêle","min":2}},{"text":"Mélange avec les pâtes, le pesto et le parmesan.","timer":null}],"kids":true,"variant":"Avec du poulet","change":"Du poulet poêlé et des tomates cerises complètent les pâtes."}]$r$::jsonb, 'claude')
