insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pate au saumon', 'Pâtes au saumon', array['pate saumon', 'tagliatelle au saumon', 'pate au saumon fume']::text[], 'dish', $r$[{"title":"Tagliatelles au saumon","intro":"Des tagliatelles dans une sauce crémeuse au saumon, citron et aneth.","minutes":20,"calories":620,"difficulty":"Facile","imageSearch":"salmon cream tagliatelle","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelles","plural":"tagliatelles","qty":400,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les tagliatelles.","timer":{"label":"Pâtes","min":10}},{"text":"Fais revenir l'échalote dans l'huile, ajoute le saumon en dés et cuis 4 min.","timer":{"label":"Poêle","min":4}},{"text":"Ajoute la crème, le zeste et un peu de jus de citron, l'aneth, sel et poivre.","timer":null},{"text":"Mélange avec les pâtes égouttées.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pâtes au saumon fumé","intro":"Encore plus rapide, avec du saumon fumé et de la crème.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"smoked salmon pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais chauffer la crème avec le zeste de citron et du poivre.","timer":null},{"text":"Mélange les pâtes avec la crème, puis le saumon fumé en lanières et la ciboulette.","timer":null}],"variant":"Au saumon fumé","change":"Le saumon fumé remplace le saumon frais : rien à cuire."},{"title":"Pâtes au saumon légères","intro":"Une version légère et verte, saumon et épinards.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"light salmon spinach pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes complètes","plural":"pâtes complètes","qty":350,"unit":"g","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"fromage frais léger","plural":"fromage frais léger","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pâtes.","timer":{"label":"Pâtes","min":10}},{"text":"Fais cuire le saumon en dés 4 min à la poêle, ajoute les épinards 1 min.","timer":{"label":"Poêle","min":5}},{"text":"Mélange avec les pâtes, le fromage frais, un peu d'eau de cuisson et le jus du citron.","timer":null}],"variant":"Plus légères","change":"La crème est remplacée par du fromage frais léger et des épinards."}]$r$::jsonb, 'claude')
