insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('one pot pasta', 'One pot pasta', array['one pot', 'pate one pot']::text[], 'dish', $r$[{"title":"One pot pasta tomate basilic","intro":"Tout cuit dans une seule casserole : les pâtes, la tomate et le basilic, en 15 minutes.","minutes":15,"calories":480,"difficulty":"Facile","imageSearch":"one pot pasta tomato basil","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets les spaghetti crus, les tomates coupées en deux, l'oignon émincé, l'ail, l'huile et le basilic dans une grande casserole.","timer":null},{"text":"Verse 1 l d'eau, sale et poivre.","timer":null},{"text":"Porte à ébullition et cuis 12 min en remuant souvent, jusqu'à ce que l'eau soit absorbée.","timer":{"label":"Cuisson","min":12}},{"text":"Sers avec le parmesan.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"One pot pasta chorizo","intro":"La version relevée du one pot, au chorizo et aux poivrons.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"one pot pasta chorizo","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"chorizo","plural":"chorizo","qty":120,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets les pâtes, le chorizo en rondelles, les tomates, le poivron et l'oignon émincés dans une casserole.","timer":null},{"text":"Verse 80 cl d'eau et sale légèrement.","timer":null},{"text":"Cuis 12 min à frémissement en remuant souvent.","timer":{"label":"Cuisson","min":12}}],"kids":true,"variant":"Au chorizo","change":"Du chorizo parfume les pâtes et la sauce."},{"title":"One pot pasta crémeux aux champignons","intro":"Un one pot tout doux, aux champignons.","minutes":15,"calories":560,"difficulty":"Facile","imageSearch":"creamy mushroom one pot pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelles","plural":"tagliatelles","qty":400,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets les pâtes, les champignons émincés, l'oignon, l'ail et le bouillon émietté dans une casserole.","timer":null},{"text":"Verse 90 cl d'eau et cuis 12 min en remuant.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute la crème et le parmesan, poivr