":"piment séché","plural":"piments séchés","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les penne.","timer":{"label":"Pâtes","min":10}},{"text":"Fais revenir l'ail et le piment dans l'huile, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le thon émietté, puis les pâtes.","timer":null}],"variant":"Au thon","change":"Du thon s'ajoute à la sauce tomate pimentée."},{"title":"Penne arrabbiata douce","intro":"La sauce tomate à l'ail, sans piquant, pour toute la famille.","minutes":20,"calories":500,"difficulty":"Facile","imageSearch":"tomato pasta kids","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":5,"unit":"cl","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les penne.","timer":{"label":"Pâtes","min":10}},{"text":"Fais revenir l'ail dans l'huile, ajoute les tomates et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la crème, puis mélange avec les pâtes et le parmesan.","timer":null}],"kids":true,"variant":"Version enfants","change":"Sans piment, avec une touche de crème et de parmesan."}]$r$::jsonb, 'claude')
