insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('risotto aux champignon', 'Risotto aux champignons', array['risotto champignon', 'risotto']::text[], 'dish', $r$[{"title":"Risotto aux champignons","intro":"Un riz crémeux cuit doucement dans le bouillon, avec des champignons et du parmesan.","minutes":35,"calories":560,"difficulty":"Moyen","imageSearch":"mushroom risotto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"riz arborio","plural":"riz arborio","qty":320,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":60,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais chauffer 1 l d'eau avec les bouillons et garde-le frémissant.","timer":null},{"text":"Fais dorer les champignons émincés dans la moitié du beurre 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote dans l'huile, ajoute le riz et nacre-le 2 min, puis verse le vin.","timer":null},{"text":"Ajoute le bouillon louche par louche, en remuant, pendant 18 min.","timer":{"label":"Cuisson","min":18}},{"text":"Hors du feu, ajoute les champignons, le reste du beurre et le parmesan.","timer":null}],"variant":"La classique","change":""},{"title":"Risotto poulet et champignons","intro":"Un risotto crémeux et complet, au poulet et aux champignons.","minutes":35,"calories":620,"difficulty":"Moyen","imageSearch":"chicken mushroom risotto","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"riz arborio","plural":"riz arborio","qty":320,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":50,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Garde 1 l de bouillon frémissant.","timer":null},{"text":"Fais dorer le poulet en dés et les champignons 8 min. Réserve.","timer":{"label":"Poêle","min":8}},{"text":"Fais revenir l'oignon, ajoute le riz 2 min, puis le bouillon louche par louche pendant 18 min.","timer":{"label":"Cuisson","min":18}},{"text":"Ajoute le poulet, les champignons, le beurre et le parmesan.","timer":null}],"kids":true,"variant":"Au poulet","change":"Du poulet poêlé rend le risotto plus complet."},{"title":"Risotto aux champignons au four","intro":"Le risotto crémeux, sans rester devant la casserole.","minutes":40,"calories":540,"difficulty":"Facile","imageSearch":"baked mushroom risotto","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz arborio","plural":"riz arborio","qty":300,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":60,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Dans une cocotte qui va au four, fais revenir l'oignon et les champignons dans le beurre, puis ajoute le riz.","timer":null},{"text":"Verse 90 cl d'eau bouillante avec les bouillons, couvre et enfourne 25 min.","timer":{"label":"Four","min":25}},{"text":"Ajoute le parmesan, mélange vivement et sers.","timer":null}],"variant":"Au four","change":"Le risotto cuit au four, sans remuer."}]$r$::jsonb, 'claude')
