insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gnocchi', 'Gnocchis', array['gnocchi a la poele', 'gnocchi poele']::text[], 'dish', $r$[{"title":"Gnocchis poêlés, sauce tomate et mozzarella","intro":"Des gnocchis dorés à la poêle, dans une sauce tomate avec de la mozzarella fondante.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"gnocchi tomato mozzarella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"gnocchi","plural":"gnocchis","qty":800,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les gnocchis dans l'huile 6 min à la poêle.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute l'ail et les tomates, sale, poivre et cuis 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la mozzarella en morceaux et le basilic, couvre 2 min pour qu'elle fonde.","timer":{"label":"Cuisson","min":2}}],"kids":true,"variant":"La classique","change":""},{"title":"Gnocchis à la crème et au gorgonzola","intro":"Des gnocchis fondants dans une sauce au bleu italien.","minutes":15,"calories":620,"difficulty":"Facile","imageSearch":"gnocchi gorgonzola cream","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"gnocchi","plural":"gnocchis","qty":800,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":120,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"noix","plural":"noix","qty":30,"unit":"g","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les gnocchis dans l'eau bouillante 2 min, jusqu'à ce qu'ils remontent.","timer":{"label":"Cuisson","min":2}},{"text":"Fais fondre le gorgonzola dans la crème à feu doux.","timer":null},{"text":"Mélange avec les gnocchis, ajoute les noix concassées et du poivre.","timer":null}],"variant":"Au gorgonzola","change":"Une sauce crémeuse au gorgonzola remplace la tomate."},{"title":"Gnocchis poêlés aux légumes","intro":"Un plat léger et coloré, prêt en 20 minutes.","minutes":20,"calories":440,"difficulty":"Facile","imageSearch":"gnocchi vegetables pan","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gnocchi","plural":"gnocchis","qty":800,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":200,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les gnocchis dans 2 c. à s. d'huile 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir les courgettes en dés avec l'ail 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les tomates cerises et les gnocchis 2 min, puis le parmesan.","timer":{"label":"Poêle","min":2}}],"variant":"Aux légumes","change":"Des courgettes et des tomates cerises poêlées avec les gnocchis."}]$r$::jsonb, 'claude')
