},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"navet","plural":"navets","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":5,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe tous les légumes en morceaux.","timer":null},{"text":"Mets-les dans une casserole, couvre d'eau avec le bouillon et cuis 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Écrase grossièrement au presse-purée, ajoute la crème, sale et poivre.","timer":null}],"kids":true,"variant":"Moulinée","change":"Les légumes sont écrasés grossièrement, avec un peu de crème."},{"title":"Soupe de légumes et vermicelles","intro":"Un bouillon de légumes en petits dés, avec des vermicelles : un vrai plat du soir.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"vegetable noodle soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"vermicelle","plural":"vermicelles","qty":60,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les légumes en petits dés et fais-les revenir 5 min dans l'