insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gaspacho', 'Gaspacho', array['gazpacho', 'soupe froide tomate']::text[], 'dish', $r$[{"title":"Gaspacho","intro":"La soupe froide andalouse : tomates, concombre et poivron, mixés avec un filet d'huile d'olive.","minutes":15,"calories":140,"difficulty":"Facile","imageSearch":"gazpacho cold tomato soup","veg":true,"oven":false,"cold":true,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":6,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de xérès","plural":"vinaigre de xérès","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les légumes en morceaux.","timer":null},{"text":"Mixe-les avec l'ail, l'huile, le vinaigre, sel et poivre, jusqu'à ce que ce soit bien lisse.","timer":null},{"text":"Mets au frais au moins 2 h avant de servir.","timer":{"label":"Frais","min":120}}],"variant":"La classique","change":""},{"title":"Gaspacho de pastèque","intro":"Un gaspacho sucré-salé, ultra rafraîchissant.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"watermelon gazpacho","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pastèque","plural":"pastèques","qty":600,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe la pastèque sans les pépins, les tomates et le concombre en morceaux.","timer":null},{"text":"Mixe avec l'huile, le jus du citron vert, la menthe et le sel.","timer":null},{"text":"Mets au frais 2 h.","timer":{"label":"Frais","min":120}}],"variant":"À la pastèque","change":"La pastèque remplace la moitié des tomates."},{"title":"Gaspacho vert","intro":"Un gaspacho tout vert, frais et crémeux.","minutes":15,"calories":180,"difficulty":"Facile","imageSearch":"green gazpacho cucumber avocado","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les légumes en morceaux.","timer":null},{"text":"Mixe avec le yaourt, le jus du citron, le basilic, l'huile et le sel.","timer":null},{"text":"Mets au frais 1 h.","timer":{"label":"Frais","min":60}}],"variant":"Vert","change":"Concombre, avocat et herbes remplacent la tomate."}]$r$::jsonb, 'claude')
