insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('minestrone', 'Minestrone', array['soupe minestrone']::text[], 'dish', $r$[{"title":"Minestrone","intro":"La soupe italienne aux légumes, haricots et petites pâtes, servie avec du parmesan.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"minestrone soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"céleri","plural":"céleris","qty":1,"unit":"","have":false},{"name":"haricot blanc","plural":"haricots blancs","qty":250,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"coquillette","plural":"coquillettes","qty":80,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, la carotte et le céleri en dés dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la courgette, les tomates, 1 l d'eau et le bouillon. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les haricots égouttés et les pâtes, et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Sers avec le parmesan.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Minestrone au pesto","intro":"Le minestrone, relevé d'une cuillère de pesto au moment de servir.","minutes":45,"calories":330,"difficulty":"Facile","imageSearch":"minestrone pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":150,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":1,"unit":"","have":false},{"name":"coquillette","plural":"coquillettes","qty":80,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":1,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et les carottes dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la pomme de terre, la courgette, les haricots verts coupés, 1 l d'eau et le bouillon. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les pâtes et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Sers avec une cuillère de pesto par bol.","timer":null}],"variant":"Au pesto","change":"Une cuillère de pesto parfume chaque bol."},{"title":"Minestrone au jambon","intro":"Le minestrone en version plus copieuse, au jambon.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"minestrone ham","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"haricot blanc","plural":"haricots blancs","qty":250,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"coquillette","plural":"coquillettes","qty":80,"unit":"g","have":false},{"name":"jambon cru","plural":"jambon cru","qty":80,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, le jambon en dés et les carottes dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la courgette, les tomates, 1 l d'eau et le bouillon. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les haricots et les pâtes, cuis 10 min.","timer":{"label":"Cuisson","min":10}}],"kids":true,"variant":"Au jambon","change":"Des dés de jambon cru parfument le bouillon."}]$r$::jsonb, 'claude')
