insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('salade nicoise', 'Salade niçoise', array['nicoise']::text[], 'dish', $r$[{"title":"Salade niçoise","intro":"La salade du Sud : thon, œufs durs, tomates, olives et anchois, avec une vinaigrette à l'huile d'olive.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"nicoise salad tuna egg","veg":false,"oven":false,"cold":true,"missing":"","origin":"Spécialité niçoise","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"olive noire","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"anchois","plural":"anchois","qty":8,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de vin","plural":"vinaigre de vin","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les œufs 10 min dans l'eau bouillante, puis refroidis-les.","timer":{"label":"Œufs","min":10}},{"text":"Coupe les tomates en quartiers, le poivron en lanières et l'oignon en rondelles fines.","timer":null},{"text":"Dispose les légumes, le thon, les œufs en quartiers, les olives et les anchois.","timer":null},{"text":"Arrose de vinaigrette : huile, vinaigre, sel et poivre.","timer":null}],"variant":"La classique","change":""},{"title":"Salade niçoise aux pommes de terre et haricots verts","intro":"La niçoise des brasseries, avec pommes de terre et haricots verts.","minutes":35,"calories":520,"difficulty":"Facile","imageSearch":"nicoise salad potatoes green beans","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":200,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"olive noire","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de vin","plural":"vinaigre de vin","qty":1,"unit":"c. à s.","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min et les haricots verts 8 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les œufs 10 min et écale-les.","timer":{"label":"Œufs","min":10}},{"text":"Prépare la vinaigrette avec la moutarde, le vinaigre, l'huile, sel et poivre.","timer":null},{"text":"Mélange tous les ingrédients coupés et arrose de vinaigrette.","timer":null}],"variant":"Plus complète","change":"Des pommes de terre et des haricots verts en font un plat complet."},{"title":"Salade niçoise végétarienne","intro":"Toutes les couleurs de la niçoise, sans poisson.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"vegetarian nicoise salad chickpeas","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"olive noire","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"vinaigre de vin","plural":"vinaigre de vin","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les œufs 10 min et refroidis-les.","timer":{"label":"Œufs","min":10}},{"text":"Coupe les tomates et le poivron.","timer":null},{"text":"Mélange avec les pois chiches égouttés, les olives et les œufs en quartiers, puis la vinaigrette.","timer":null}],"variant":"Végétarienne","change":"Le thon et les anchois sont remplacés par des pois chiches."}]$r$::jsonb, 'claude')
