insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('salade cesar', 'Salade César', array['caesar salad', 'salade caesar']::text[], 'dish', $r$[{"title":"Salade César","intro":"De la romaine croquante, du poulet doré, des croûtons et une sauce César au parmesan.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"caesar salad chicken","veg":false,"oven":false,"cold":true,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"laitue romaine","plural":"laitues romaines","qty":1,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"pain de mie","plural":"pains de mie","qty":3,"unit":"tranches","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet dans 1 c. à s. d'huile 10 min, puis coupe-le en tranches.","timer":{"label":"Poêle","min":10}},{"text":"Coupe le pain en cubes et fais-le dorer 3 min dans le reste d'huile avec l'ail.","timer":{"label":"Poêle","min":3}},{"text":"Mélange la mayonnaise, le jus du citron, la moitié du parmesan, sel et poivre.","timer":null},{"text":"Mélange la salade avec la sauce, puis ajoute le poulet, les croûtons et le reste de parmesan.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Salade César légère","intro":"La César en version légère, toujours aussi gourmande.","minutes":25,"calories":400,"difficulty":"Facile","imageSearch":"light caesar salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"laitue romaine","plural":"laitues romaines","qty":1,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"pain complet","plural":"pains complets","qty":2,"unit":"tranches","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":30,"unit":"g","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le poulet 10 min à la poêle antiadhésive et tranche-le.","timer":{"label":"Poêle","min":10}},{"text":"Grille le pain en cubes à sec 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Mélange le yaourt, la moutarde, le jus de citron, la moitié du parmesan, sel et poivre.","timer":null},{"text":"Mélange la salade avec la sauce et ajoute le reste.","timer":null}],"variant":"Plus légère","change":"La sauce est faite au yaourt et les croûtons sont grillés à sec."},{"title":"Salade César aux crevettes","intro":"La César revisitée avec des crevettes poêlées à l'ail.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"shrimp caesar salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"laitue romaine","plural":"laitues romaines","qty":1,"unit":"","have":false},{"name":"crevette","plural":"crevettes","qty":300,"unit":"g","have":false},{"name":"pain de mie","plural":"pains de mie","qty":3,"unit":"tranches","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais sauter les crevettes avec l'ail dans 1 c. à s. d'huile 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Fais dorer les cubes de pain dans le reste d'huile 3 min.","timer":{"label":"Poêle","min":3}},{"text":"Mélange la mayonnaise, le jus de citron et la moitié du parmesan.","timer":null},{"text":"Mélange la salade avec la sauce, les crevettes, les croûtons et le parmesan.","timer":null}],"variant":"Aux crevettes","change":"Des crevettes à l'ail remplacent le poulet."}]$r$::jsonb, 'claude')
