insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('salade de lentille', 'Salade de lentilles', array['lentille en salade', 'salade lentille']::text[], 'dish', $r$[{"title":"Salade de lentilles","intro":"Des lentilles vertes tièdes avec échalote, persil et une vinaigrette à la moutarde.","minutes":35,"calories":340,"difficulty":"Facile","imageSearch":"lentil salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"vinaigre de vin","plural":"vinaigre de vin","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min dans l'eau avec la carotte coupée en dés.","timer":{"label":"Cuisson","min":25}},{"text":"Prépare la vinaigrette avec la moutarde, le vinaigre, l'huile, sel et poivre.","timer":null},{"text":"Égoutte les lentilles et mélange-les tièdes avec les échalotes émincées, le persil et la vinaigrette.","timer":null}],"variant":"La classique","change":""},{"title":"Salade de lentilles au saumon fumé","intro":"Une salade de lentilles chic, au saumon fumé.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"lentil salad smoked salmon","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":150,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":5,"unit":"cl","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min et égoutte-les.","timer":{"label":"Cuisson","min":25}},{"text":"Mélange l'huile, le jus du citron, sel et poivre, et assaisonne les lentilles avec l'échalote.","timer":null},{"text":"Ajoute le saumon en lanières et une cuillère de crème à l'aneth.","timer":null}],"variant":"Au saumon fumé","change":"Du saumon fumé et de la crème à l'aneth complètent la salade."},{"title":"Salade de lentilles, feta et légumes croquants","intro":"Une salade complète et colorée, idéale à emporter.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"lentil feta salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"lentille verte","plural":"lentilles vertes","qty":250,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":150,"unit":"g","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les lentilles 25 min et laisse-les refroidir.","timer":{"label":"Cuisson","min":25}},{"text":"Coupe le concombre, les tomates et l'oignon.","timer":null},{"text":"Mélange tout avec la feta émiettée, la menthe, le jus du citron, l'huile, sel et poivre.","timer":null}],"variant":"Feta et légumes","change":"De la feta, du concombre et des tomates cerises rendent la salade plus fraîche."}]$r$::jsonb, 'claude')
