insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('taboule', 'Taboulé', array['taboule libanai', 'salade de boulgour', 'taboule oriental']::text[], 'dish', $r$[{"title":"Taboulé","intro":"La semoule fraîche à la tomate, au concombre, à la menthe et au citron.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"couscous tabbouleh salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":250,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Verse 25 cl d'eau bouillante salée sur la semoule, couvre 5 min et égrène à la fourchette.","timer":{"label":"Repos","min":5}},{"text":"Coupe les tomates, le concombre et l'oignon en petits dés.","timer":null},{"text":"Mélange avec la semoule, la menthe et le persil ciselés, le jus des citrons, l'huile, sel et poivre.","timer":null},{"text":"Mets au frais 1 h.","timer":{"label":"Frais","min":60}}],"kids":true,"variant":"La classique","change":""},{"title":"Taboulé libanais","intro":"Le vrai taboulé libanais : surtout du persil, avec un peu de boulgour.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"lebanese tabbouleh parsley","veg":true,"oven":false,"cold":true,"missing":"","origin":"Plat libanais","serves":4,"items":[{"name":"persil plat","plural":"persil plat","qty":150,"unit":"g","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"boulgour","plural":"boulgour","qty":60,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais tremper le boulgour 15 min dans l'eau froide et égoutte-le bien.","timer":{"label":"Trempage","min":15}},{"text":"Hache finement le persil et la menthe, coupe les tomates et les oignons en petits dés.","timer":null},{"text":"Mélange tout avec le jus des citrons, l'huile et le sel.","timer":null}],"variant":"Libanais","change":"Beaucoup de persil et un peu de boulgour, à la libanaise."},{"title":"Taboulé au quinoa","intro":"Le taboulé frais, au quinoa.","minutes":25,"calories":330,"difficulty":"Facile","imageSearch":"quinoa tabbouleh","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le quinoa 12 min dans l'eau salée et laisse-le refroidir.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe les légumes en petits dés.","timer":null},{"text":"Mélange avec le quinoa, la menthe, le jus des citrons, l'huile, sel et poivre.","timer":null}],"variant":"Au quinoa","change":"Le quinoa remplace la semoule, sans gluten."}]$r$::jsonb, 'claude')
