insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('chili con carne', 'Chili con carne', array['chili', 'chili con carne maison']::text[], 'dish', $r$[{"title":"Chili con carne","intro":"Bœuf haché, haricots rouges et tomates, relevés au cumin et au piment.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chili con carne","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"haricot rouge","plural":"haricots rouges","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"c. à c.","have":false},{"name":"piment en poudre","plural":"piment en poudre","qty":0.5,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons, le poivron en dés et l'ail dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la viande et les épices, et fais dorer 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les tomates, sale et laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}},{"text":"Ajoute les haricots rouges égouttés et cuis 10 min. Sers avec du riz.","timer":{"label":"Cuisson","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Chili sin carne","intro":"Le chili tout végé, aux haricots rouges, lentilles et maïs.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"vegetarian chili beans","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"haricot rouge","plural":"haricots rouges","qty":400,"unit":"g","have":false},{"name":"lentille corail","plural":"lentilles corail","qty":100,"unit":"g","have":false},{"name":"maïs","plural":"maïs","qty":150,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"c. à c.","have":false},{"name":"paprika fumé","plural":"paprika fumé","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons, le poivron et l'ail dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les épices, les lentilles rincées, les tomates et 20 cl d'eau. Laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Ajoute les haricots et le maïs, et cuis 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarienne","change":"La viande est remplacée par des lentilles et plus de haricots."},{"title":"Chili con carne doux","intro":"Le chili pour toute la famille, doux et gourmand.","minutes":45,"calories":580,"difficulty":"Facile","imageSearch":"mild chili kids","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"haricot rouge","plural":"haricots rouges","qty":400,"unit":"g","have":false},{"name":"maïs","plural":"maïs","qty":150,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans l'huile, puis la viande avec le cumin 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les tomates et laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}},{"text":"Ajoute les haricots et le maïs, cuis 5 min, et sers avec le cheddar.","timer":{"label":"Cuisson","min":5}}],"kids":true,"variant":"Version enfants","change":"Sans piment, avec un peu de maïs et servi avec du fromage râpé."}]$r$::jsonb, 'claude')
