insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('curry de poulet', 'Curry de poulet', array['poulet curry', 'poulet au curry', 'curry poulet coco', 'poulet coco']::text[], 'dish', $r$[{"title":"Poulet au curry et lait de coco","intro":"Du poulet tendre dans une sauce crémeuse au lait de coco et au curry.","minutes":35,"calories":520,"difficulty":"Facile","imageSearch":"chicken coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration indienne","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, l'ail et le gingembre dans l'huile 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute le poulet en morceaux et le curry, fais dorer 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Verse les tomates et le lait de coco, sale et laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Sers avec du riz et la coriandre.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Curry de poulet léger","intro":"Un curry parfumé et léger, plein de légumes.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"light chicken curry yogurt","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration indienne","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à s.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans l'huile, ajoute le poulet en morceaux et le curry 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la courgette, le poivron et les tomates, et laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Hors du feu, ajoute le yaourt et sale.","timer":null}],"variant":"Plus léger","change":"Le lait de coco est remplacé par du yaourt et plus de légumes."},{"title":"Curry de poulet aux légumes et pommes de terre","intro":"Un curry complet, sans besoin de riz.","minutes":40,"calories":500,"difficulty":"Facile","imageSearch":"chicken potato curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Inspiration indienne","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et le poulet en morceaux avec le curry 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les pommes de terre en cubes, le lait de coco et 10 cl d'eau. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les petits pois et cuis 5 min.","timer":{"label":"Cuisson","min":5}}],"kids":true,"variant":"Aux légumes","change":"Des pommes de terre et des petits pois en font un plat complet."}]$r$::jsonb, 'claude')
