insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet tikka masala', 'Poulet tikka masala', array['tikka masala', 'chicken tikka masala']::text[], 'dish', $r$[{"title":"Poulet tikka masala","intro":"Du poulet mariné au yaourt et aux épices, dans une sauce tomate crémeuse.","minutes":45,"calories":540,"difficulty":"Moyen","imageSearch":"chicken tikka masala","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet en morceaux et mélange-le avec le yaourt, la moitié des épices et du sel. Laisse mariner 15 min.","timer":{"label":"Marinade","min":15}},{"text":"Fais dorer le poulet dans l'huile 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'oignon, l'ail et le gingembre, ajoute le reste des épices puis les tomates. Cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la crème et le poulet, et laisse mijoter 10 min. Sers avec du riz basmati.","timer":{"label":"Mijotage","min":10}}],"variant":"La classique","change":""},{"title":"Poulet tikka masala léger","intro":"Toutes les épices du tikka, avec une sauce plus légère.","minutes":45,"calories":400,"difficulty":"Moyen","imageSearch":"light tikka masala","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais mariner le poulet en morceaux avec un yaourt et la moitié des épices 15 min.","timer":{"label":"Marinade","min":15}},{"text":"Fais-le dorer 6 min, puis ajoute l'oignon, l'ail, le reste des épices et les tomates.","timer":{"label":"Poêle","min":6}},{"text":"Laisse mijoter 15 min, puis ajoute le second yaourt hors du feu.","timer":{"label":"Mijotage","min":15}}],"variant":"Plus léger","change":"La crème est remplacée par du yaourt."},{"title":"Tikka masala de pois chiches","intro":"La sauce tikka, avec des pois chiches et des épinards.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"chickpea tikka masala","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"pois chiche","plural":"pois chiches","qty":500,"unit":"g","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":100,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail dans l'huile avec les épices 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute les tomates et laisse mijoter 10 min.","timer":{"label":"Mijotage","min":10}},{"text":"Ajoute les pois chiches, la crème et les épinards, et cuis 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarienne","change":"Le poulet est remplacé par des pois chiches et des épinards."}]$r$::jsonb, 'claude')
