insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('butter chicken', 'Butter chicken', array['poulet au beurre', 'murgh makhani']::text[], 'dish', $r$[{"title":"Butter chicken","intro":"Le poulet au beurre indien : une sauce tomate douce, beurrée et crémeuse.","minutes":45,"calories":620,"difficulty":"Moyen","imageSearch":"butter chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais mariner le poulet en morceaux avec le yaourt, 1 c. à c. de garam masala et du sel 15 min.","timer":{"label":"Marinade","min":15}},{"text":"Fais dorer le poulet dans la moitié du beurre 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais fondre l'oignon, l'ail et le gingembre dans le reste du beurre, ajoute les épices et les tomates. Cuis 10 min puis mixe.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la crème et le poulet, et laisse mijoter 10 min.","timer":{"label":"Mijotage","min":10}}],"kids":true,"variant":"La classique","change":""},{"title":"Butter chicken express","intro":"Le butter chicken pour les soirs pressés.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"quick butter chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"coulis de tomate","plural":"coulis de tomate","qty":40,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en morceaux dans le beurre 6 min avec l'ail.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le garam masala et le coulis, et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la crème, sale et laisse épaissir 3 min.","timer":{"label":"Cuisson","min":3}}],"kids":true,"variant":"Express","change":"Sans marinade ni sauce mixée : prêt en 25 minutes."},{"title":"Butter paneer","intro":"La sauce butter chicken, avec un fromage qui se tient à la cuisson.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"paneer butter masala","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"paneer","plural":"paneer","qty":400,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":15,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le paneer en cubes et fais-le dorer 4 min dans la moitié du beurre.","timer":{"label":"Poêle","min":4}},{"text":"Fais fondre l'oignon et l'ail dans le reste du beurre, ajoute les épices et les tomates, et cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la crème et le paneer et laisse mijoter 5 min.","timer":{"label":"Mijotage","min":5}}],"variant":"Végétarienne","change":"Le poulet est remplacé par du paneer, ou de la halloumi."}]$r$::jsonb, 'claude')
