insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('curry de legume', 'Curry de légumes', array['curry vegetarien', 'curry legume coco', 'curry vegetal']::text[], 'dish', $r$[{"title":"Curry de légumes au lait de coco","intro":"Des légumes fondants dans une sauce coco parfumée au curry.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"vegetable coconut curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration indienne","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"chou-fleur","plural":"choux-fleurs","qty":0.5,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon dans l'huile avec le curry 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute les pommes de terre et les carottes en morceaux, le lait de coco et 15 cl d'eau. Cuis 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute le chou-fleur en bouquets et la courgette, cuis encore 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute les pois chiches, sale et sers avec du riz.","timer":null}],"variant":"La classique","change":""},{"title":"Curry de patate douce et épinards","intro":"Un curry doux, à la patate douce fondante.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"sweet potato spinach curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Inspiration indienne","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":2,"unit":"","have":false},{"name":"pousse d'épinard","plural":"pousses d'épinard","qty":150,"unit":"g","have":false},{"name":"lentille corail","plural":"lentilles corail","qty":100,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon avec le curry 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute la patate douce en cubes, les lentilles, le lait de coco et 30 cl d'eau. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les épinards 2 min et sale.","timer":{"label":"Cuisson","min":2}}],"variant":"Patate douce","change":"Patate douce et épinards remplacent les autres légumes."},{"title":"Curry vert de légumes","intro":"Un curry thaï parfumé, au basilic et au citron vert.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"thai green vegetable curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat thaïlandais","serves":4,"items":[{"name":"pâte de curry vert","plural":"pâte de curry vert","qty":2,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":150,"unit":"g","have":false},{"name":"champignon","plural":"champignons","qty":150,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir la pâte de curry dans l'huile 1 min, puis verse le lait de coco.","timer":null},{"text":"Ajoute les légumes en morceaux et cuis 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute la sauce soja, le jus du citron vert et le basilic.","timer":null}],"variant":"Curry vert thaï","change":"La pâte de curry vert remplace le curry en poudre."}]$r$::jsonb, 'claude')
