insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('dal de lentille', 'Dal de lentilles', array['dal', 'dhal', 'dahl', 'dal de lentille corail']::text[], 'dish', $r$[{"title":"Dal de lentilles corail","intro":"Des lentilles corail fondantes, au lait de coco et aux épices douces.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"red lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"lentille corail","plural":"lentilles corail","qty":250,"unit":"g","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curry","plural":"curry","qty":1,"unit":"c. à s.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, l'ail et le gingembre dans l'huile avec les épices 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Ajoute les lentilles rincées, les tomates, le lait de coco et 50 cl d'eau.","timer":null},{"text":"Laisse cuire 20 min en remuant, jusqu'à ce que ce soit crémeux.","timer":{"label":"Cuisson","min":20}},{"text":"Sale et sers avec du riz ou du pain naan.","timer":null}],"variant":"La classique","change":""},{"title":"Dal aux épinards","intro":"Le dal crémeux, avec des épinards pour le vert.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"spinach lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat indien","serves":4,"items":[{"name":"le