insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('fajita', 'Fajitas', array['fajita poulet']::text[], 'dish', $r$[{"title":"Fajitas au poulet","intro":"Des lanières de poulet et de poivrons épicées, roulées dans des tortillas.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"chicken fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"épices fajitas","plural":"épices fajitas","qty":2,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet, les poivrons et l'oignon en lanières.","timer":null},{"text":"Fais dorer le poulet dans l'huile avec les épices 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les légumes et cuis 6 min, ils doivent rester croquants.","timer":{"label":"Poêle","min":6}},{"text":"Réchauffe les tortillas et garnis-les avec la crème et la poêlée.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Fajitas au bœuf","intro":"Les fajitas en version bœuf, avec du guacamole.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"beef fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"bœuf à griller","plural":"bœuf à griller","qty":500,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"épices fajitas","plural":"épices fajitas","qty":2,"unit":"c. à s.","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Écrase l'avocat avec le jus du citron vert et du sel.","timer":null},{"text":"Fais saisir le bœuf en lanières avec les épices 3 min à feu vif.","timer":{"label":"Poêle","min":3}},{"text":"Ajoute les poivrons et l'oignon et cuis 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Garnis les tortillas chaudes de bœuf, de légumes et d'avocat.","timer":null}],"variant":"Au bœuf","change":"Des lanières de bœuf remplacent le poulet."},{"title":"Fajitas végétariennes","intro":"Des fajitas pleines de légumes et de haricots.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"vegetarian fajitas beans","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat tex-mex","serves":4,"items":[{"name":"haricot noir","plural":"haricots noirs","qty":400,"unit":"g","have":false},{"name":"champignon","plural":"champignons","qty":200,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"épices fajitas","plural":"épices fajitas","qty":2,"unit":"c. à s.","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"ste