insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('riz cantonai', 'Riz cantonais', array['riz frit', 'riz cantonnai']::text[], 'dish', $r$[{"title":"Riz cantonais","intro":"Le riz sauté du traiteur : jambon, œufs, petits pois et sauce soja.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"cantonese fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"riz cuit","plural":"riz cuit","qty":600,"unit":"g","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Bats les œufs et fais-les cuire en omelette fine dans 1 c. à s. d'huile, puis coupe-la en lanières.","timer":{"label":"Poêle","min":2}},{"text":"Fais sauter le riz froid dans le reste d'huile 5 min à feu vif.","timer":{"label":"Wok","min":5}},{"text":"Ajoute le jambon, les petits pois et les oignons 3 min.","timer":{"label":"Wok","min":3}},{"text":"Ajoute la sauce soja et l'omelette, et mélange.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Riz cantonais aux crevettes","intro":"Le riz sauté, avec des crevettes juteuses.","minutes":20,"calories":460,"difficulty":"Facile","imageSearch":"shrimp fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"riz cuit","plural":"riz cuit","qty":600,"unit":"g","have":false},{"name":"crevette","plural":"crevettes","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire les œufs brouillés dans 1 c. à s. d'huile. Réserve.","timer":{"label":"Poêle","min":2}},{"text":"Fais sauter les crevettes 2 min, puis le riz 5 min à feu vif.","timer":{"label":"Wok","min":7}},{"text":"Ajoute les petits pois, les oignons, les œufs et la sauce soja.","timer":null}],"variant":"Aux crevettes","change":"Des crevettes remplacent le jambon."},{"title":"Riz sauté aux légumes","intro":"Un riz sauté plein de légumes, prêt en 15 minutes.","minutes":15,"calories":400,"difficulty":"Facile","imageSearch":"vegetable fried rice","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"riz cuit","plural":"riz cuit","qty":600,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais sauter les carottes et le poivron en petits dés 4 min dans l'huile.","timer":{"label":"Wok","min":4}},{"text":"Ajoute le riz et fais sauter 5 min.","timer":{"label":"Wok","min":5}},{"text":"Pousse le riz sur le côté, brouille les œufs, puis mélange avec les petits pois et la sauce soja.","timer":null}],"variant":"Végétarienne","change":"Le jambon est remplacé par des légumes croquants."}]$r$::jsonb, 'claude')
