insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('porc au caramel', 'Porc au caramel', array['porc caramel', 'porc au caramel vietnamien']::text[], 'dish', $r$[{"title":"Porc au caramel","intro":"Des morceaux de porc fondants, laqués dans un caramel au nuoc-mâm.","minutes":60,"calories":560,"difficulty":"Moyen","imageSearch":"vietnamese caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"échine de porc","plural":"échine de porc","qty":800,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":3,"unit":"c. à s.","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le porc en cubes.","timer":null},{"text":"Fais un caramel avec le sucre et 2 c. à s. d'eau, jusqu'à ce qu'il soit ambré.","timer":{"label":"Caramel","min":5}},{"text":"Ajoute le porc, les oignons émincés et l'ail, et mélange bien.","timer":null},{"text":"Verse le nuoc-mâm, la sauce soja et 20 cl d'eau, et laisse mijoter 45 min jusqu'à ce que la sauce soit sirupeuse.","timer":{"label":"Mijotage","min":45}}],"variant":"La classique","change":""},{"title":"Poulet au caramel","intro":"Le même caramel laqué, avec du poulet, plus rapide.","minutes":35,"calories":500,"difficulty":"Facile","imageSearch":"caramel chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":8,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":2,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Coupe le poulet en morceaux.","timer":null},{"text":"Fais un caramel ambré avec le sucre et un peu d'eau.","timer":{"label":"Caramel","min":5}},{"text":"Ajoute le poulet, l'oignon, l'ail et le gingembre, puis le nuoc-mâm, la soja et 10 cl d'eau.","timer":null},{"text":"Laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}}],"kids":true,"variant":"Au poulet","change":"Le porc est remplacé par des hauts de cuisse de poulet."},{"title":"Porc au caramel express","intro":"Le porc au caramel pour un soir de semaine.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"quick caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe le filet mignon en fines tranches.","timer":null},{"text":"Fais-les saisir dans l'huile 4 min.","timer":{"label":"Poêle","min":4}},{"text":"Ajoute le sucre, l'ail, la sauce soja et le nuoc-mâm, et laisse caraméliser 5 min.","timer":{"label":"Poêle","min":5}}],"variant":"Express","change":"Avec du filet mignon en fines tranches, c'est prêt en 25 minutes."}]$r$::jsonb, 'claude')
