insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('ramen', 'Ramen', array['ramen maison', 'soupe ramen']::text[], 'dish', $r$[{"title":"Ramen au poulet","intro":"Un bouillon parfumé au soja et au gingembre, des nouilles, du poulet, un œuf mollet et des légumes.","minutes":40,"calories":520,"difficulty":"Moyen","imageSearch":"chicken ramen bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat japonais","serves":4,"items":[{"name":"nouilles ramen","plural":"nouilles ramen","qty":300,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"champignon","plural":"champignons","qty":150,"unit":"g","have":false},{"name":"pak choï","plural":"pak choïs","qty":2,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais cuire les œufs 6 min 30 dans l'eau bouillante, puis refroidis-les.","timer":{"label":"Œufs","min":6}},{"text":"Fais chauffer 1,5 l d'eau avec les bouillons, la sauce soja, le gingembre et l'ail.","timer":null},{"text":"Fais pocher le poulet 12 min dans le bouillon, puis tranche-le.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute les champignons et le pak choï 3 min, et fais cuire les nouilles à part.","timer":{"label":"Cuisson","min":3}},{"text":"Sers les nouilles dans des bols avec le bouillon, le poulet, l'œuf coupé en deux et l'oignon.","timer":null}],"variant":"La classique","change":""},{"title":"Ramen végétarien au miso","intro":"Un ramen réconfortant au miso, au tofu et aux légumes.","minutes":30,"calories":460,"difficulty":"Moyen","imageSearch":"miso ramen vegetarian","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat japonais","serves":4,"items":[{"name":"nouilles ramen","plural":"nouilles ramen","qty":300,"unit":"g","have":false},{"name":"pâte de miso","plural":"pâte de miso","qty":3,"unit":"c. à s.","have":false},{"name":"tofu ferme","plural":"tofu ferme","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"champignon","plural":"champignons","qty":150,"unit":"g","have":false},{"name":"épinard","plural":"épinards","qty":100,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais cuire les œufs 6 min 30 et refroidis-les.","timer":{"label":"Œufs","min":6}},{"text":"Fais chauffer 1,5 l d'eau avec les bouillons, ajoute les champignons et le tofu en cubes 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Hors du feu, délaye le miso dans le bouillon et ajoute la sauce soja et les épinards.","timer":null},{"text":"Fais cuire les nouilles et sers avec le bouillon, l'œuf et l'oignon.","timer":null}],"variant":"Végétarienne","change":"Un bouillon au miso remplace le bouillon de volaille."},{"title":"Ramen express","intro":"Un bol de ramen fumant en 15 minutes.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"quick ramen","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat japonais","serves":4,"items":[{"name":"nouilles ramen","plural":"nouilles ramen","qty":300,"unit":"g","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais chauffer 1,2 l d'eau avec les bouillons et la sauce soja.","timer":null},{"text":"Ajoute la carotte en julienne et les nouilles, et cuis 4 min.","timer":{"label":"Cuisson","min":4}},{"text":"Casse les œufs dans le bouillon et laisse-les pocher 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Sers avec l'oignon émincé.","timer":null}],"variant":"Express","change":"Avec un bouillon tout prêt et des restes de légumes, en 15 minutes."}]$r$::jsonb, 'claude')
