insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('curry vert thai', 'Curry vert thaï', array['curry vert', 'curry vert poulet', 'green curry']::text[], 'dish', $r$[{"title":"Curry vert thaï au poulet","intro":"Du poulet et des légumes dans un lait de coco parfumé à la pâte de curry vert et au basilic.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"thai green curry chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat thaïlandais","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"pâte de curry vert","plural":"pâte de curry vert","qty":2,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":150,"unit":"g","have":false},{"name":"sauce soja","plural":"sauce soja","qty":1,"unit":"c. à s.","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir la pâte de curry dans l'huile 1 min.","timer":null},{"text":"Ajoute le poulet en lanières et fais-le dorer 4 min.","timer":{"label":"Cuisson","min":4}},{"text":"Verse le lait de coco, ajoute les légumes et cuis 12 min.","timer":{"label":"Cuisson","min":12}},{"text":"Ajoute la sauce soja, le jus du citron vert et le basilic. Sers avec du riz.","timer":null}],"variant":"La classique","change":""},{"title":"Curry vert thaï aux crevettes","intro":"Le curry vert, avec des crevettes juteuses.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"thai green curry shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat thaïlandais","serves":4,"items":[{"name":"crevette","plural":"crevettes","qty":400,"unit":"g","have":false},{"name":"pâte de curry vert","plural":"pâte de curry vert","qty":2,"unit":"c. à s.","have":false},{"name":"lait de coco","plural":"lait de coco","qty":40,"unit":"cl","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"pois gourmand","plural":"pois gourmands","qty":150,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir la pâte de curry dans l'huile 1 min, puis verse le lait de coco.","timer":null},{"text":"Ajoute le poivron et les pois gourmands, cuis 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute les crevettes 3 min, puis le citron vert et le basilic.","timer":{"label":"Cuisson","min":3}}],"variant":"Aux crevettes","change":"Des crevettes remplacent le poulet."},{"title":"Curry vert thaï léger","intro":"Toute la saveur du curry vert, en plus léger.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"light thai green curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat thaïlandais","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"pâte de curry vert","plural":"pâte de curry vert","qty":2,"unit":"c. à s.","have":false},{"name":"lait de coco léger","plural":"lait de coco léger","qty":20,"unit":"cl","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":1,"unit":"","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais chauffer la pâte de curry dans une cocotte avec un peu de lait de coco 1 min.","timer":null},{"text":"Ajoute le reste du lait de coco, 20 cl d'eau et le bouillon.","timer":null},{"text":"Ajoute le poulet en lanières et les légumes, cuis 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute le citron vert et le basilic.","timer":null}],"variant":"Plus léger","change":"Moitié lait de coco, moitié bouillon."}]$r$::jsonb, 'claude')
