insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet aigre dou', 'Poulet aigre-doux', array['porc aigre dou', 'aigre douce']::text[], 'dish', $r$[{"title":"Poulet aigre-doux","intro":"Du poulet croustillant dans une sauce aigre-douce à l'ananas et aux poivrons.","minutes":30,"calories":540,"difficulty":"Facile","imageSearch":"sweet and sour chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":3,"unit":"c. à s.","have":false},{"name":"ananas","plural":"ananas","qty":200,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Mélange le ketchup, le vinaigre, le sucre, la sauce soja et 10 cl d'eau.","timer":null},{"text":"Coupe le poulet en dés, roule-les dans la fécule et fais-les dorer dans l'huile 6 min. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter les poivrons et l'oignon en morceaux 4 min, ajoute l'ananas.","timer":{"label":"Wok","min":4}},{"text":"Verse la sauce, laisse épaissir 2 min et ajoute le poulet. Sers avec du riz.","timer":{"label":"Wok","min":2}}],"kids":true,"variant":"La classique","change":""},{"title":"Porc aigre-doux","intro":"Le classique des restaurants chinois, au porc.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"sweet and sour pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":3,"unit":"c. à s.","have":false},{"name":"ananas","plural":"ananas","qty":200,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare la sauce : ketchup, vinaigre, sucre et 10 cl d'eau.","timer":null},{"text":"Coupe le porc en dés, enrobe-le de fécule et fais-le dorer 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter le poivron, l'oignon et l'ananas 4 min.","timer":{"label":"Wok","min":4}},{"text":"Ajoute la sauce et le porc, et laisse épaissir 2 min.","timer":{"label":"Wok","min":2}}],"variant":"Au porc","change":"Du filet de porc remplace le poulet."},{"title":"Poulet aigre-doux léger","intro":"L'aigre-doux en version légère, avec plus de légumes.","minutes":25,"calories":400,"difficulty":"Facile","imageSearch":"light sweet sour chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"ananas","plural":"ananas","qty":150,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"brocoli","plural":"brocolis","qty":1,"unit":"","have":false},{"name":"jus d'ananas","plural":"jus d'ananas","qty":10,"unit":"cl","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":1,"unit":"c. à s.","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais dorer le poulet en dés 6 min dans l'huile.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le poivron, le brocoli en petits bouquets et l'ananas, cuis 5 min.","timer":{"label":"Wok","min":5}},{"text":"Mélange le jus d'ananas, la soja, le vinaigre et la fécule, verse et laisse épaissir 2 min.","timer":{"label":"Wok","min":2}}],"variant":"Plus léger","change":"Le poulet n'est pas enrobé de fécule, et la sauce est moins sucrée."}]$r$::jsonb, 'claude')
