insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('couscou', 'Couscous', array['couscou royal', 'couscou marocain', 'couscou poulet']::text[], 'dish', $r$[{"title":"Couscous au poulet et merguez","intro":"La semoule, un bouillon parfumé aux épices, des légumes fondants, du poulet et des merguez.","minutes":90,"calories":720,"difficulty":"Moyen","imageSearch":"couscous chicken merguez vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat maghrébin","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":400,"unit":"g","have":false},{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":4,"unit":"","have":false},{"name":"merguez","plural":"merguez","qty":4,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"navet","plural":"navets","qty":2,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet et les oignons dans l'huile dans un grand faitout.","timer":null},{"text":"Ajoute les épices, les tomates, les carottes et les navets en tronçons, puis 1,5 l d'eau. Laisse mijoter 40 min.","timer":{"label":"Mijotage","min":40}},{"text":"Ajoute les courgettes et les pois chiches et cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Fais griller les merguez 10 min.","timer":{"label":"Gril","min":10}},{"text":"Verse le même volume d'eau bouillante salée que de semoule, couvre 5 min, puis égrène avec le beurre. Sers avec le bouillon, les légumes et les viandes.","timer":{"label":"Repos","min":5}}],"kids":true,"variant":"La classique","change":""},{"title":"Couscous végétarien","intro":"Un couscous aux légumes généreux et parfumé.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"vegetable couscous","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat maghrébin","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":350,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"navet","plural":"navets","qty":2,"unit":"","have":false},{"name":"potiron","plural":"potirons","qty":300,"unit":"g","have":false},{"name":"pois chiche","plural":"pois chiches","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"c. à c.","have":false},{"name":"raisin sec","plural":"raisins secs","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons dans l'huile avec les épices.","timer":null},{"text":"Ajoute les tomates, les carottes, les navets et 1,2 l d'eau. Laisse mijoter 25 min.","timer":{"label":"Mijotage","min":25}},{"text":"Ajoute les courgettes, le potiron, les pois chiches et les raisins, cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Prépare la semoule avec le même volume d'eau bouillante salée et égrène-la.","timer":null}],"variant":"Végétarienne","change":"Uniquement des légumes et des pois chiches."},{"title":"Couscous express au poulet","intro":"Le goût du couscous pour un soir de semaine.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"quick chicken couscous","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat maghrébin","serves":4,"items":[{"name":"semoule","plural":"semoule","qty":300,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en morceaux et l'oignon dans l'huile avec les épices 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute les carottes et les courgettes en dés, les tomates et 50 cl d'eau. Cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les pois chiches 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Prépare la semoule et sers avec le bouillon.","timer":null}],"kids":true,"variant":"Express","change":"Avec des blancs de poulet et des légumes en petits morceaux, prêt en 35 minutes."}]$r$::jsonb, 'claude')
