insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tajine de poulet', 'Tajine de poulet', array['tajine', 'tajine poulet citron olive', 'tajine au poulet']::text[], 'dish', $r$[{"title":"Tajine de poulet aux citrons confits et olives","intro":"Du poulet fondant, parfumé au gingembre et au safran, avec des citrons confits et des olives.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"chicken tagine lemon olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat marocain","serves":4,"items":[{"name":"poulet en morceaux","plural":"poulets en morceaux","qty":1,"unit":"","have":false},{"name":"citron confit","plural":"citrons confits","qty":2,"unit":"","have":false},{"name":"olive verte","plural":"olives vertes","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"curcuma","plural":"curcuma","qty":1,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir le poulet dans l'huile avec les oignons émincés et l'ail.","timer":null},{"text":"Ajoute les épices, 30 cl d'eau, sel et poivre.","timer":null},{"text":"Couvre et laisse mijoter 45 min.","timer":{"label":"Mijotage","min":45}},{"text":"Ajoute les citrons confits en quartiers et les olives, et cuis 15 min à découvert.","timer":{"label":"Cuisson","min":15}},{"text":"Parsème de coriandre et sers avec de la semoule ou du pain.","timer":null}],"variant":"La classique","change":""},{"title":"Tajine de poulet aux abricots","intro":"Un tajine doux et parfumé, aux abricots et aux amandes.","minutes":75,"calories":580,"difficulty":"Moyen","imageSearch":"chicken apricot tagine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat marocain","serves":4,"items":[{"name":"poulet en morceaux","plural":"poulets en morceaux","qty":1,"unit":"","have":false},{"name":"abricot sec","plural":"abricots secs","qty":150,"unit":"g","have":false},{"name":"amande","plural":"amandes","qty":50,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"miel","plural":"miel","qty":1,"unit":"c. à s.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir le poulet et les oignons dans l'huile avec les épices.","timer":null},{"text":"Ajoute 30 cl d'eau et laisse mijoter 40 min.","timer":{"label":"Mijotage","min":40}},{"text":"Ajoute les abricots et le miel, et cuis 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Fais griller les amandes et parsème-les au moment de servir.","timer":null}],"kids":true,"variant":"Aux abricots","change":"Des abricots secs et du miel donnent une sauce sucrée-salée."},{"title":"Tajine de légumes","intro":"Un tajine coloré, aux légumes fondants et aux épices douces.","minutes":50,"calories":380,"difficulty":"Facile","imageSearch":"vegetable tagine","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat marocain","serves":4,"items":[{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"c. à c.","have":false},{"name":"citron confit","plural":"citrons confits","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons dans l'huile avec les épices.","timer":null},{"text":"Ajoute les légumes en morceaux, les tomates et 30 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 35 min.","timer":{"label":"Mijotage","min":35}},{"text":"Ajoute les pois chiches et le citron confit 10 min.","timer":{"label":"Cuisson","min":10}}],"variant":"Végétarienne","change":"Uniquement des légumes et des pois chiches."}]$r$::jsonb, 'claude')
