insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('paella', 'Paella', array['paella valenciana', 'paella royale', 'paella fruit de mer']::text[], 'dish', $r$[{"title":"Paella","intro":"Le riz au safran, avec poulet, chorizo, crevettes, moules et petits pois.","minutes":60,"calories":650,"difficulty":"Moyen","imageSearch":"seafood paella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":350,"unit":"g","have":false},{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":4,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"crevette","plural":"crevettes","qty":8,"unit":"","have":false},{"name":"moule","plural":"moules","qty":500,"unit":"g","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"safran","plural":"safran","qty":1,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet en morceaux et le chorizo dans l'huile, dans une grande poêle.","timer":null},{"text":"Ajoute l'oignon, le poivron et les tomates en dés, cuis 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le riz, le safran, puis 1 l d'eau chaude avec les bouillons. Ne remue plus.","timer":null},{"text":"Laisse cuire 15 min, puis ajoute les crevettes, les moules et les petits pois.","timer":{"label":"Cuisson","min":15}},{"text":"Couvre et cuis encore 10 min, jusqu'à ce que les moules s'ouvrent.","timer":{"label":"Cuisson","min":10}}],"variant":"La classique","change":""},{"title":"Paella au poulet","intro":"La paella des familles, au poulet et au chorizo.","minutes":50,"calories":620,"difficulty":"Moyen","imageSearch":"chicken chorizo paella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":350,"unit":"g","have":false},{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":6,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"safran","plural":"safran","qty":1,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet et le chorizo dans l'huile.","timer":null},{"text":"Ajoute l'oignon, le poivron et les tomates, cuis 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le riz, le safran et 1 l de bouillon chaud.","timer":null},{"text":"Cuis 20 min sans remuer, ajoute les petits pois les 5 dernières minutes.","timer":{"label":"Cuisson","min":20}}],"kids":true,"variant":"Au poulet","change":"Sans fruits de mer, avec poulet et chorizo."},{"title":"Paella de légumes","intro":"Une paella colorée aux légumes du soleil.","minutes":45,"calories":480,"difficulty":"Moyen","imageSearch":"vegetable paella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":350,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"haricot vert","plural":"haricots verts","qty":150,"unit":"g","have":false},{"name":"petits pois","plural":"petits pois","qty":100,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"safran","plural":"safran","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et les poivrons dans l'huile 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute la courgette, les haricots et les tomates en dés 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le riz, le safran et 1 l de bouillon chaud.","timer":null},{"text":"Cuis 20 min sans remuer, ajoute les petits pois à la fin.","timer":{"label":"Cuisson","min":20}}],"variant":"Végétarienne","change":"Des légumes remplacent la viande et les fruits de mer."}]$r$::jsonb, 'claude')
