insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('moussaka', 'Moussaka', array['moussaka grecque']::text[], 'dish', $r$[{"title":"Moussaka","intro":"Des couches d'aubergines, de viande d'agneau à la tomate et à la cannelle, sous une béchamel gratinée.","minutes":100,"calories":640,"difficulty":"Moyen","imageSearch":"greek moussaka","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat grec","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"agneau haché","plural":"agneau haché","qty":500,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cannelle","plural":"cannelle","qty":0.5,"unit":"c. à c.","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"parmesan râpé","plural":"parmesan râpé","qty":40,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe les aubergines en tranches, badigeonne-les d'huile et fais-les rôtir 20 min au four à 200 °C.","timer":{"label":"Four","min":20}},{"text":"Fais revenir l'oignon, l'ail et la viande, ajoute les tomates et la cannelle, et laisse mijoter 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait, puis ajoute l'œuf battu.","timer":null},{"text":"Alterne aubergines et viande dans un plat, termine par la béchamel et le parmesan.","timer":null},{"text":"Enfourne 40 min à 180 °C.","timer":{"label":"Four","min":40}}],"variant":"La classique","change":""},{"title":"Moussaka au bœuf","intro":"La moussaka familiale, au bœuf.","minutes":100,"calories":620,"difficulty":"Moyen","imageSearch":"beef moussaka","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat grec","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cannelle","plural":"cannelle","qty":0.5,"unit":"c. à c.","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":50,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais rôtir les tranches d'aubergines huilées 20 min à 200 °C.","timer":{"label":"Four","min":20}},{"text":"Prépare la sauce à la viande avec l'oignon, l'ail, le bœuf, les tomates et la cannelle, 20 min.","timer":{"label":"Mijotage","min":20}},{"text":"Prépare la béchamel.","timer":null},{"text":"Monte la moussaka, termine par la béchamel et l'emmental, et enfourne 40 min à 180 °C.","timer":{"label":"Four","min":40}}],"variant":"Au bœuf","change":"Le bœuf haché remplace l'agneau, plus doux et moins cher."},{"title":"Moussaka végétarienne aux lentilles","intro":"Une moussaka généreuse, aux lentilles et aux aubergines.","minutes":90,"calories":520,"difficulty":"Moyen","imageSearch":"lentil moussaka vegetarian","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat grec","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"lentille verte","plural":"lentilles vertes","qty":200,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cannelle","plural":"cannelle","qty":0.5,"unit":"c. à c.","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":5,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais rôtir les aubergines huilées 20 min à 200 °C.","timer":{"label":"Four","min":20}},{"text":"Fais cuire les lentilles 20 min, puis mélange-les avec l'oignon et l'ail revenus, les tomates et la cannelle.","timer":{"label":"Cuisson","min":20}},{"text":"Prépare la béchamel.","timer":null},{"text":"Monte la moussaka, termine par la béchamel et la feta émiettée, et enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"Végétarienne","change":"Les lentilles remplacent la viande."}]$r$::jsonb, 'claude')
