insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('falafel', 'Falafels', array['falafel maison']::text[], 'dish', $r$[{"title":"Falafels","intro":"Des boulettes de pois chiches aux herbes, croustillantes dehors, moelleuses dedans, avec une sauce au yaourt.","minutes":40,"calories":450,"difficulty":"Moyen","imageSearch":"falafel","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat libanais","serves":4,"items":[{"name":"pois chiche sec","plural":"pois chiches secs","qty":250,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"c. à c.","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"huile de friture","plural":"huile de friture","qty":50,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"La veille, fais tremper les pois chiches secs dans l'eau froide.","timer":null},{"text":"Mixe-les égouttés avec l'oignon, l'ail, les herbes, le cumin, la farine et le sel.","timer":null},{"text":"Forme des petites boulettes.","timer":null},{"text":"Fais-les frire 4 min dans l'huile chaude, jusqu'à ce qu'elles soient dorées.","timer":{"label":"Friture","min":4}},{"text":"Sers avec le yaourt mélangé au jus de citron.","timer":null}],"variant":"La classique","change":""},{"title":"Falafels au four","intro":"Les falafels plus légers, cuits au four.","minutes":45,"calories":360,"difficulty":"Moyen","imageSearch":"baked falafel","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat li