insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('shakshuka', 'Shakshuka', array['chakchouka', 'oeuf a la tomate', 'chakchouka tunisienne']::text[], 'dish', $r$[{"title":"Shakshuka","intro":"Des œufs pochés dans une sauce tomate aux poivrons, au cumin et au paprika.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"shakshuka eggs tomato","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat du Maghreb","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et les poivrons en lanières dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute l'ail, les épices et les tomates, sale et laisse mijoter 10 min.","timer":{"label":"Mijotage","min":10}},{"text":"Creuse des petits trous et casse un œuf dans chacun.","timer":null},{"text":"Couvre et laisse cuire 6 min, jusqu'à ce que les blancs soient pris.","timer":{"label":"Cuisson","min":6}},{"text":"Parsème de coriandre et sers avec du pain.","timer":null}],"variant":"La classique","change":""},{"title":"Shakshuka verte","intro":"Une shakshuka toute verte, à la feta.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"green shakshuka spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"épinard","plural":"épinards","qty":300,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre le poireau et la courgette en dés dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute l'ail, le cumin et les épinards jusqu'à ce qu'ils tombent.","timer":null},{"text":"Casse les œufs dans les légumes, couvre et cuis 6 min.","timer":{"label":"Cuisson","min":6}},{"text":"Parsème de feta.","timer":null}],"variant":"Verte","change":"Épinards, courgette et herbes remplacent la tomate."},{"title":"Shakshuka aux merguez","intro":"La shakshuka plus copieuse, avec des merguez.","minutes":30,"calories":460,"difficulty":"Facile","imageSearch":"shakshuka merguez","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"merguez","plural":"merguez","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les merguez coupées en tronçons 5 min. Réserve.","timer":{"label":"Poêle","min":5}},{"text":"Fais revenir l'oignon et le poivron 8 min, ajoute le cumin et les tomates, cuis 10 min.","timer":{"label":"Mijotage","min":18}},{"text":"Remets les merguez, casse les œufs et cuis 6 min à couvert.","timer":{"label":"Cuisson","min":6}}],"variant":"Aux merguez","change":"Des merguez grillées s'ajoutent à la sauce."}]$r$::jsonb, 'claude')
