insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet yassa', 'Poulet yassa', array['yassa']::text[], 'dish', $r$[{"title":"Poulet yassa","intro":"Le plat sénégalais : du poulet mariné au citron, mijoté avec beaucoup d'oignons fondants.","minutes":80,"calories":520,"difficulty":"Moyen","imageSearch":"chicken yassa","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat sénégalais","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":6,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":4,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":2,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange le jus des citrons, la moutarde, l'ail, les oignons émincés, sel et poivre. Fais mariner le poulet dedans 30 min.","timer":{"label":"Marinade","min":30}},{"text":"Fais dorer le poulet égoutté dans l'huile. Réserve.","timer":null},{"text":"Fais fondre les oignons de la marinade 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Remets le poulet avec le reste de la marinade, le bouillon, le piment et 20 cl d'eau. Laisse mijoter 30 min. Sers avec du riz.","timer":{"label":"Mijotage","min":30}}],"variant":"La classique","change":""},{"title":"Poisson yassa","intro":"Le yassa au poisson, citronné et fondant.","minutes":50,"calories":420,"difficulty":"Moyen","imageSearch":"fish yassa","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat 