,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":800,"unit":"g","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":4,"unit":"c. à s.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"chou blanc","plural":"choux blancs","qty":0.25,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le bœuf en cubes dans l'huile avec les oignons.","timer":null},{"text":"Ajoute l'ail, les tomates, le beurre de cacahuète délayé et 80 cl d'eau.","timer":null},{"text":"Laisse mijoter 1 h 15, puis ajoute les carottes et le chou, et cuis 30 min.","timer":{"label":"Mijotage","min":105}}],"variant":"Au bœuf","change":"Du bœuf à mijoter remplace le poulet."},{"title":"Mafé de légumes","intro":"Un mafé végé, crémeux et réconfortant.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"vegetable peanut stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat d'Afrique de l'Ouest","serves":4,"items":[{"name":"patate douce","plural":"patates douces","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"pois chiche","plural":"pois chiches","qty":250,"unit":"g","have":false},{"name":"beurre de cacahuète","plural":"beurre de cacahuète","qty":3,"unit":"c. à s.","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail dans l'huile.","timer":null},{"text":"Ajoute les tomates, le beurre de cacahuète délayé et 40 cl d'eau.","timer":null},{"text":"Ajoute les légumes en morceaux et laisse mijoter 30 min.","timer":{"label":"Mijotage","min":30}},{"text":"Ajoute les pois chiches 5 min.","timer":{"label":"Cuisson","min":5}}],"variant":"Végétarienne","change":"Patate douce, carottes et pois chiches remplacent la viande."}]$r$::jsonb, 'claude')
