insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('crepe', 'Crêpes', array['pate a crepe', 'crepe sucree', 'crepe maison']::text[], 'dish', $r$[{"title":"Crêpes","intro":"La pâte à crêpes inratable, fine et légère, pour le goûter ou la Chandeleur.","minutes":40,"calories":220,"difficulty":"Facile","imageSearch":"french crepes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":30,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets la farine, le sucre et une pincée de sel dans un saladier, et creuse un puits.","timer":null},{"text":"Ajoute les œufs, puis le lait petit à petit en fouettant pour éviter les grumeaux.","timer":null},{"text":"Ajoute le beurre fondu et laisse reposer 30 min si tu peux.","timer":{"label":"Repos","min":30}},{"text":"Fais cuire les crêpes dans une poêle chaude légèrement beurrée, 1 min de chaque côté.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Crêpes sans lactose","intro":"Des crêpes aussi fines, sans produits laitiers.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"dairy free crepes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"lait d'avoine","plural":"lait d'avoine","qty":50,"unit":"cl","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":2,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la farine, le sucre et le sel, puis ajoute les œufs.","timer":null},{"text":"Verse le lait d'avoine petit à petit en fouettant, puis l'huile.","timer":null},{"text":"Laisse reposer 30 min.","timer":{"label":"Repos","min":30}},{"text":"Fais cuire les crêpes dans une poêle chaude huilée.","timer":null}],"kids":true,"dessert":true,"variant":"Sans lait","change":"Le lait de vache est remplacé par du lait d'avoine et le beurre par de l'huile."},{"title":"Galettes de sarrasin complètes","intro":"Les galettes bretonnes complètes : jambon, œuf et emmental.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"buckwheat galette ham egg cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité bretonne","serves":4,"items":[{"name":"farine de sarrasin","plural":"farine de sarrasin","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":5,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la farine, 1 œuf, une pincée de sel et 60 cl d'eau froide. Laisse reposer 1 h.","timer":{"label":"Repos","min":60}},{"text":"Fais cuire une galette dans une poêle beurrée 2 min.","timer":{"label":"Poêle","min":2}},{"text":"Retourne-la, ajoute emmental, jambon et casse un œuf au centre.","timer":null},{"text":"Replie les bords en carré et laisse cuire jusqu'à ce que le blanc soit pris.","timer":{"label":"Poêle","min":3}}],"kids":true,"variant":"Galettes salées","change":"Farine de sarrasin, avec jambon, œuf et fromage."}]$r$::jsonb, 'claude')
