":"levure de boulanger","qty":10,"unit":"g","have":false},{"name":"sucre perlé","plural":"sucre perlé","qty":150,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Délaye la levure dans le lait tiède.","timer":null},{"text":"Mélange la farine, les œufs, le lait et le sel, puis incorpore le beurre mou.","timer":null},{"text":"Laisse lever 1 h dans un endroit tiède.","timer":{"label":"Levée","min":60}},{"text":"Ajoute le sucre perlé, forme des boules et fais-les cuire 4 min dans le gaufrier.","timer":{"label":"Gaufrier","min":4}}],"dessert":true,"variant":"De Liège","change":"Une pâte levée avec du sucre perlé qui caramélise."},{"title":"Gaufres légères","intro":"Des gaufres moelleuses et plus légères.","minutes":35,"calories":220,"difficulty":"Facile","imageSearch":"light waffles","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait demi-écrémé","plural":"laits demi-écrémé","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromages blanc","qty":100,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":30,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":20,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Mélange la farine, la levure et le sucre.","timer":null},{"text":"Ajoute les œufs, le fromage blanc, le lait et le beurre fondu.","timer":null},{"text":"Fais cuire 4 min dans le gaufrier chaud.","timer":{"label":"Gaufrier","min":4}}],"kids":true,"dessert":true,"variant":"Plus légères","change":"Moins de beurre, et du fromage blanc dans la pâte."}]$r$::jsonb, 'claude')
