insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pancake', 'Pancakes', array['pancake americain']::text[], 'dish', $r$[{"title":"Pancakes","intro":"Des pancakes épais et moelleux, à servir avec du sirop d'érable.","minutes":25,"calories":280,"difficulty":"Facile","imageSearch":"fluffy pancakes","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"farine","plural":"farines","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":30,"unit":"cl","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":40,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":30,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"sirop d'érable","plural":"sirop d'érable","qty":null,"unit":"","have":false}],"steps":[{"text":"Mélange la farine, la levure, le sucre et une pincée de sel.","timer":null},{"text":"Ajoute les œufs, le lait et le beurre fondu, et mélange juste ce qu'il faut.","timer":null},{"text":"Verse une petite louche de pâte dans une poêle chaude beurrée.","timer":null},{"text":"Retourne quand des bulles apparaissent, après 2 min, et cuis 1 min de l'autre côté.","timer":{"label":"Poêle","min":3}},{"text":"Sers avec le sirop d'érable.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Pancakes à la banane","intro":"Des pancakes moelleux à la banane.","minutes":25,"calories":270,"difficulty":"Facile","imageSearch":"banana pancakes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"banane","plural":"bananes","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"nam