s":[{"text":"Mélange le lait, les œufs et la moitié du sucre.","timer":null},{"text":"Trempe rapidement les tranches de brioche.","timer":null},{"text":"Fais-les dorer dans le beurre, saupoudre du reste de sucre et laisse caraméliser 1 min de chaque côté.","timer":{"label":"Poêle","min":5}}],"kids":true,"dessert":true,"variant":"Brioché","change":"La brioche remplace le pain, avec une touche de caramel."},{"title":"Pain perdu salé","intro":"Le pain perdu en plat du soir, gratiné au fromage.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"savory french toast ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain rassis","plural":"pains rassis","qty":8,"unit":"tranches","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Bats les œufs avec le lait, sel et poivre.","timer":null},{"text":"Trempe le pain et fais-le dorer dans le beurre 2 min d'un côté.","timer":{"label":"Poêle","min":2}},{"text":"Retourne, ajoute le jambon et l'emmental, couvre et cuis 3 min.","timer":{"label":"Poêle","min":3}}],"kids":true,"variant":"Salé","change":"Version salée au fromage et au jambon."}]$r$::jsonb, 'claude')
