insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gateau au chocolat', 'Gâteau au chocolat', array['fondant au chocolat', 'moelleu au chocolat', 'gateau chocolat']::text[], 'dish', $r$[{"title":"Gâteau au chocolat","intro":"Le gâteau au chocolat fondant au cœur, le dessert préféré de tous.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"chocolate cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat et le beurre ensemble.","timer":null},{"text":"Fouette les œufs avec le sucre, puis ajoute le chocolat et la farine.","timer":null},{"text":"Verse dans un moule beurré et enfourne 22 min : le centre doit rester tremblotant.","timer":{"label":"Four","min":22}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Gâteau au chocolat sans beurre","intro":"Le fondant, en version plus légère.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"light chocolate cake applesauce","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":150,"unit":"g","have":false},{"name":"compote de pommes","plural":"compote de pommes","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"farine","plural":"farines","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat et mélange-le avec la compote.","timer":null},{"text":"Ajoute les œufs battus avec le sucre, puis la farine.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"dessert":true,"variant":"Plus léger","change":"Le beurre est remplacé par de la compote de pommes."},{"title":"Gâteau au chocolat sans gluten","intro":"Un fondant au chocolat et aux amandes, sans gluten.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"flourless chocolate almond cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":120,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":80,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 170 °C.","timer":null},{"text":"Fais fondre le chocolat et le beurre.","timer":null},{"text":"Fouette les œufs avec le sucre, ajoute le chocolat puis la poudre d'amande.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"dessert":true,"variant":"Sans gluten","change":"La farine est remplacée par de la poudre d'amande."}]$r$::jsonb, 'claude')
