insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('brownie', 'Brownie', array['brownie aux noi']::text[], 'dish', $r$[{"title":"Brownie aux noix","intro":"Un brownie dense et fondant, avec des noix croquantes.","minutes":35,"calories":450,"difficulty":"Facile","imageSearch":"chocolate brownie walnuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":150,"unit":"g","have":false},{"name":"sucre roux","plural":"sucre roux","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"farine","plural":"farines","qty":80,"unit":"g","have":false},{"name":"noix","plural":"noix","qty":80,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat et le beurre.","timer":null},{"text":"Fouette les œufs avec le sucre, ajoute le chocolat, la farine, une pincée de sel et les noix concassées.","timer":null},{"text":"Verse dans un moule carré et enfourne 20 min.","timer":{"label":"Four","min":20}},{"text":"Laisse refroidir avant de couper en carrés.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Brownie à la banane","intro":"Un brownie moelleux et anti-gaspi, avec des bananes bien mûres.","minutes":35,"calories":330,"difficulty":"Facile","imageSearch":"banana brownie","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":150,"unit":"g","have":false},{"name":"banane","plural":"bananes","qty":2,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":60,"unit":"g","have":false},{"name":"sucre roux","plural":"sucre roux","qty":60,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"farine","plural":"farines","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat avec le beurre.","timer":null},{"text":"Écrase les bananes et mélange avec les œufs, le sucre, le chocolat et la farine.","timer":null},{"text":"Enfourne 22 min.","timer":{"label":"Four","min":22}}],"kids":true,"dessert":true,"variant":"À la banane","change":"De la banane remplace une partie du beurre et du sucre."},{"title":"Brownie sans gluten","intro":"Un brownie fondant aux amandes, sans gluten.","minutes":35,"calories":480,"difficulty":"Facile","imageSearch":"gluten free brownie","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":120,"unit":"g","have":false},{"name":"sucre roux","plural":"sucre roux","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"poudre d'amande","plural":"poudre d'amande","qty":80,"unit":"g","have":false},{"name":"noisette","plural":"noisettes","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat et le beurre.","timer":null},{"text":"Ajoute les œufs battus avec le sucre, la poudre d'amande et les noisettes concassées.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"dessert":true,"variant":"Sans gluten","change":"La farine est remplacée par de la poudre d'amande."}]$r$::jsonb, 'claude')
