insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('cake au citron', 'Cake au citron', array['gateau au citron', 'cake citron']::text[], 'dish', $r$[{"title":"Cake au citron","intro":"Un cake moelleux et parfumé, nappé d'un glaçage au citron.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"lemon loaf cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":180,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":120,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"sucre glace","plural":"sucre glace","qty":80,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fouette les œufs et le sucre, ajoute le beurre fondu, le zeste et le jus d'un citron.","timer":null},{"text":"Ajoute la farine et la levure, et verse dans un moule à cake.","timer":null},{"text":"Enfourne 40 min.","timer":{"label":"Four","min":40}},{"text":"Mélange le sucre glace avec le jus de l'autre citron et nappe le cake refroidi.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Cake au citron et pavot","intro":"Le cake au citron, avec des graines de pavot.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"lemon poppy seed cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":160,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":120,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"graines de pavot","plural":"graines de pavot","qty":2,"unit":"c. à s.","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange les œufs et le sucre, puis le beurre, le zeste et le jus des citrons.","timer":null},{"text":"Ajoute la farine, la levure et le pavot.","timer":null},{"text":"Enfourne 40 min dans un moule à cake.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"Au pavot","change":"Des graines de pavot ajoutent du croquant."},{"title":"Cake au citron léger","intro":"Le cake au citron, moelleux et plus léger.","minutes":55,"calories":240,"difficulty":"Facile","imageSearch":"light lemon yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":4,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":2,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange les œufs, le sucre, le yaourt, l'huile, le zeste et le jus des citrons.","timer":null},{"text":"Ajoute la farine et la levure.","timer":null},{"text":"Enfourne 40 min.","timer":{"label":"Four","min":40}}],"dessert":true,"variant":"Plus léger","change":"Le beurre est remplacé par du yaourt."}]$r$::jsonb, 'claude')
