la pâte sur une plaque et pique-la.","timer":null},{"text":"Coupe les pommes en lamelles très fines et dispose-les en rosace.","timer":null},{"text":"Saupoudre de sucre et parsème de beurre.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"dessert":true,"variant":"Tarte fine","change":"Une pâte feuilletée fine, sans compote."},{"title":"Tarte normande","intro":"La tarte aux pommes à la normande, avec sa crème dorée.","minutes":60,"calories":380,"difficulty":"Facile","imageSearch":"normandy apple tart cream","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité normande","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"pomme","plural":"pommes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule.","timer":null},{"text":"Dispose les pommes en quartiers fins.","timer":null},{"text":"Enfourne 15 min.","timer":{"label":"Four","min":15}},{"text":"Bats les œufs, la crème et les sucres, verse sur les pommes et enfourne encore 25 min.","timer":{"label":"Four","min":25}}],"dessert":true,"variant":"Normande","change":"Un appareil à la crème et aux œufs recouvre les pommes."}]$r$::jsonb, 'claude')
