insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tarte tatin', 'Tarte tatin', array['tatin']::text[], 'dish', $r$[{"title":"Tarte tatin","intro":"La tarte renversée : des pommes caramélisées sous une pâte croustillante.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"pomme","plural":"pommes","qty":7,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Fais un caramel ambré avec le sucre dans un moule qui va sur le feu, ajoute le beurre.","timer":{"label":"Caramel","min":6}},{"text":"Range les pommes en quartiers serrés dans le caramel et laisse cuire 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Couvre de pâte en rentrant les bords et enfourne 30 min.","timer":{"label":"Four","min":30}},{"text":"Laisse tiédir 10 min puis retourne sur un plat.","timer":{"label":"Repos","min":10}}],"dessert":true,"variant":"La classique","change":""},{"title":"Tatin de poires","intro":"La tatin revisitée, aux poires caramélisées.","minutes":60,"calories":370,"difficulty":"Moyen","imageSearch":"pear tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte feuilletée","plural":"pâtes feuilletées","qty":1,"unit":"","have":false},{"name":"poire","plural":"poires","qty":6,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":100,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Fais un caramel avec le sucre, ajoute le beurre.","timer":{"label":"Caramel","min":6}},{"text":"Range les poires en qua