insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tarte au citron', 'Tarte au citron', array['tarte au citron meringuee', 'tarte citron']::text[], 'dish', $r$[{"title":"Tarte au citron meringuée","intro":"Une crème au citron acidulée, sous une meringue légère et dorée.","minutes":80,"calories":380,"difficulty":"Moyen","imageSearch":"lemon meringue tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":80,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Fais cuire la pâte à blanc 20 min.","timer":{"label":"Four","min":20}},{"text":"Fais chauffer le jus et le zeste des citrons avec 100 g de sucre, les jaunes, la fécule et le beurre, en remuant jusqu'à épaississement.","timer":{"label":"Crème","min":5}},{"text":"Verse sur la pâte.","timer":null},{"text":"Monte les blancs en neige ferme avec le reste du sucre et étale-les sur la crème.","timer":null},{"text":"Fais dorer 5 min sous le gril du four.","timer":{"label":"Gril","min":5}}],"dessert":true,"variant":"La classique","change":""},{"title":"Tarte au citron","intro":"La tarte au citron toute simple, acidulée et fondante.","minutes":60,"calories":340,"difficulty":"Facile","imageSearch":"lemon tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":150,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":100,"unit":"g","have":false}],"steps":[{"text":"Fais cuire la pâte à blanc 20 min à 180 °C.","timer":{"label":"Four","min":20}},{"text":"Fais épaissir le jus et le zeste des citrons avec le sucre et les œufs, en remuant à feu doux.","timer":{"label":"Crème","min":5}},{"text":"Ajoute le beurre en morceaux hors du feu.","timer":null},{"text":"Verse sur la pâte et laisse prendre 2 h au frais.","timer":{"label":"Frais","min":120}}],"dessert":true,"variant":"Sans meringue","change":"Sans meringue : juste la crème au citron."},{"title":"Tarte au citron vert","intro":"Une tarte fraîche au citron vert, façon key lime pie.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"key lime pie","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat américain","serves":4,"items":[{"name":"biscuit sec","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":4,"unit":"","have":false},{"name":"lait concentré sucré","plural":"lait concentré sucré","qty":400,"unit":"g","have":false},{"name":"jaune d'œuf","plural":"jaunes d'œufs","qty":3,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 170 °C.","timer":null},{"text":"Écrase les biscuits, mélange-les au beurre fondu et tasse-les dans un moule.","timer":null},{"text":"Mélange le lait concentré, les jaunes, le jus et le zeste des citrons verts, et verse sur la base.","timer":null},{"text":"Enfourne 15 min, puis laisse prendre 3 h au frais.","timer":{"label":"Four","min":15}}],"dessert":true,"variant":"Citron vert","change":"Le citron vert remplace le citron jaune, avec une base biscuit."}]$r$::jsonb, 'claude')
